input.content:
/* cell-j01-s01 实体目录管理台 — 应用核心
 * 架构：单一数据源（内存实体数组）+ 派生渲染；
 * 状态归属：selection（选择集）/ query（筛选器）/ mode（预览模态）/ viewport（树展开）四类状态各有唯一属主。
 * 零误伤契约：computeAffected() 是预览与执行的唯一共同来源——确认列表与实际作用集合逐 id 一致。 */
(function () {
  'use strict';

  var SEED = window.SEED;
  var STATUSES = SEED.statuses;
  var STATUS_BY_ID = {};
  STATUSES.forEach(function (s) { STATUS_BY_ID[s.id] = s; });

  // ---------- 索引 ----------
  var CAT_BY_ID = {};
  SEED.categories.forEach(function (c) { CAT_BY_ID[c.id] = c; });
  var CHILDREN = {};
  SEED.categories.forEach(function (c) {
    if (c.parentId) { (CHILDREN[c.parentId] = CHILDREN[c.parentId] || []).push(c); }
  });
  var DOMAIN_CATS = {};
  SEED.categories.forEach(function (c) {
    if (!c.parentId) { (DOMAIN_CATS[c.domainId] = DOMAIN_CATS[c.domainId] || []).push(c); }
  });
  var ENT_BY_ID = {};
  SEED.entities.forEach(function (e) { ENT_BY_ID[e.id] = e; });

  // ---------- 状态（各有唯一属主） ----------
  var state = {
    // query —— 筛选器：只决定可见行，永不触碰 selection
    scopeNodeId: 'root',
    query: '',
    statusFilter: {},        // {statusId:true}
    sortKey: 'id',
    sortDir: 1,
    // selection —— 选择集：仅 行复选 / 范围全选 / 清空 / 仅保留可见 四种显式动作可变
    selection: {},           // {entityId:true}
    // viewport —— 树展开状态
    expanded: { root: true },
    // mode —— 预览确认模态（暂存待执行操作）
    pending: null,
    // 操作记录
    ops: [],
    lastOp: null,
    // 交互辅助
    anchor: null,            // shift 范围选择锚点
    detailOpen: {},          // 行内展开
    warnListOpen: false,
    opsPanelOpen: false
  };

  SEED.domains.forEach(function (d) { state.expanded[d.id] = true; });
  SEED.categories.forEach(function (c) { if (c.depth <= 1) state.expanded[c.id] = true; });

  // ---------- 纯派生 ----------
  function allEntities() { return SEED.entities; }

  function catPath(catId) {
    var parts = [], c = CAT_BY_ID[catId];
    while (c) { parts.unshift(c.name); c = c.parentId ? CAT_BY_ID[c.parentId] : null; }
    return parts;
  }
  function pathText(catId) { return catPath(catId).join(' / '); }
  function statusOf(e) { return STATUS_BY_ID[e.status]; }

  function subtreeCatIds(nodeId) {
    if (nodeId === 'root') return SEED.categories.map(function (c) { return c.id; });
    var out = [nodeId], queue = [nodeId];
    while (queue.length) {
      var cur = queue.shift();
      (CHILDREN[cur] || []).forEach(function (ch) { out.push(ch.id); queue.push(ch.id); });
    }
    return out;
  }

  function entitiesInNode(nodeId) {
    var ids = subtreeCatIds(nodeId), set = {};
    ids.forEach(function (id) { set[id] = true; });
    return allEntities().filter(function (e) { return set[e.categoryId]; });
  }

  function visibleList() {
    var q = state.query.trim().toLowerCase();
    var scopeIds = subtreeCatIds(state.scopeNodeId), scopeSet = {};
    scopeIds.forEach(function (id) { scopeSet[id] = true; });
    var list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (state.statusFilter[e.status]) {
        // 状态筛选语义：勾选的状态=排除该状态（筛选chip显示为「隐藏 xx」）？
        // —— 采用「显示所选状态」的常规语义：见下方判断
      }
      return true;
    });
    // 状态筛选：未勾选任何状态 = 全部显示；有勾选 = 只显示勾选状态
    var active = STATUSES.some(function (s) { return state.statusFilter[s.id]; });
    if (active) list = list.filter(function (e) { return state.statusFilter[e.status]; });
    if (q) {
      list = list.filter(function (e) {
        return (e.id + ' ' + e.name + ' ' + e.owner + ' ' + e.tags.join(' ') + ' ' + pathText(e.categoryId))
          .toLowerCase().indexOf(q) !== -1;
      });
    }
    var k = state.sortKey, dir = state.sortDir;
    list.sort(function (a, b) {
      var va, vb;
      if (k === 'status') { va = statusOf(a).label; vb = statusOf(b).label; }
      else if (k === 'path') { va = pathText(a.categoryId); vb = pathText(b.categoryId); }
      else { va = a[k]; vb = b[k]; }
      return va < vb ? -dir : va > vb ? dir : (a.id < b.id ? -1 : 1);
    });
    return list;
  }

  // 节点聚合：直接计数 / 累计计数 / 状态分布（树、表格、状态栏三处同源）
  function nodeAgg(nodeId) {
    var list = entitiesInNode(nodeId);
    var dist = {};
    STATUSES.forEach(function (s) { dist[s.id] = 0; });
    list.forEach(function (e) { dist[e.status] += 1; });
    return { total: list.length, dist: dist };
  }

  function selectedIds() {
    return Object.keys(state.selection);
  }
  function hiddenSelected() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    return selectedIds().filter(function (id) { return !vis[id]; });
  }

  // ---------- 零误伤核心：预览与执行共用同一计算 ----------
  // 返回 {apply:[{id,before,after}], noop:[{id,reason}]}
  function computeAffected(ids, op) {
    var apply = [], noop = [];
    ids.forEach(function (id) {
      var e = ENT_BY_ID[id];
      var item = { id: id, name: e.name, path: pathText(e.categoryId), e: e };
      if (op.type === 'status') {
        if (e.status === op.target) { item.reason = '已是「' + statusOf(e).label + '」'; noop.push(item); return; }
        item.before = e.status; item.after = op.target;
      } else if (op.type === 'move') {
        if (e.categoryId === op.target) { item.reason = '已在该类别'; noop.push(item); return; }
        item.beforePath = pathText(e.categoryId); item.afterPath = pathText(op.target);
      } else if (op.type === 'tag-add') {
        var add = op.tags.filter(function (t) { return e.tags.indexOf(t) === -1; });
        if (!add.length) { item.reason = '已含全部目标标签'; noop.push(item); return; }
        item.beforeTags = e.tags.slice(); item.afterTags = e.tags.concat(add);
      } else if (op.type === 'tag-remove') {
        if (e.tags.indexOf(op.tag) === -1) { item.reason = '不含标签「' + op.tag + '」'; noop.push(item); return; }
        item.beforeTags = e.tags.slice();
        item.afterTags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        item.before = e.status;
      }
      apply.push(item);
    });
    return { apply: apply, noop: noop };
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // ---------- 渲染 ----------
  var $ = function (sel) { return document.querySelector(sel); };

  function statusBadge(sid, extra) {
    var s = STATUS_BY_ID[sid];
    return '<span class="badge tone-' + s.tone + (extra ? ' ' + extra : '') + '">' + s.label + '</span>';
  }

  function renderTree() {
    var host = $('#tree');
    var html = treeNode('root', '全部实体', null, 0);
    SEED.domains.forEach(function (d) {
      var kids = DOMAIN_CATS[d.id] || [];
      var inner = kids.map(function (c) { return catNode(c, 1); }).join('');
      html += domainNode(d, inner);
    });
    host.innerHTML = html;
  }

  function domainNode(d, inner) {
    var agg = nodeAgg(d.id);
    var open = !!state.expanded[d.id];
    return '<div class="tnode depth-0' + (state.scopeNodeId === d.id ? ' scoped' : '') + '" data-node="' + d.id + '">' +
      '<div class="trow" role="treeitem" aria-expanded="' + open + '" tabindex="0" data-act="toggle" data-id="' + d.id + '">' +
      '<span class="caret' + (open ? ' open' : '') + '">▸</span>' +
      '<span class="tname">' + esc(d.name) + '</span>' + countsHtml(agg) + microBar(agg) + '</div>' +
      (open ? '<div class="tkids">' + inner + '</div>' : '') +
      '</div>';
  }

  function catNode(c, depth) {
    var agg = nodeAgg(c.id);
    var kids = CHILDREN[c.id] || [];
    var open = !!state.expanded[c.id];
    var row = '<div class="trow' + (state.scopeNodeId === c.id ? ' scoped' : '') + '" role="treeitem" tabindex="0"' +
      (kids.length ? ' aria-expanded="' + open + '"' : '') +
      ' data-act="' + (kids.length ? 'toggle' : 'scope') + '" data-id="' + c.id + '">' +
      (kids.length ? '<span class="caret' + (open ? ' open' : '') + '">▸</span>' : '<span class="caret leaf"></span>') +
      '<span class="tname">' + esc(c.name) + '</span>' + countsHtml(agg) + microBar(agg) + '</div>';
    var childHtml = kids.length && open ? '<div class="tkids">' + kids.map(function (ch) { return catNode(ch, depth + 1); }).join('') + '</div>' : '';
    return '<div class="tnode depth-' + depth + '">' + row + childHtml + '</div>';
  }

  function treeNode(id, name, aggIgnored, depth) {
    var agg = nodeAgg(id === 'root' ? 'root' : id);
    var list = id === 'root' ? { total: agg.total } : agg;
    return '<div class="tnode depth-0' + (state.scopeNodeId === 'root' ? ' scoped' : '') + '" data-node="root">' +
      '<div class="trow" role="treeitem" tabindex="0" data-act="scope" data-id="root">' +
      '<span class="caret leaf"></span><span class="tname">' + esc(name) + '</span>' +
      countsHtml({ total: agg.total }) + microBar(agg) + '</div></div>';
  }

  function countsHtml(agg) {
    var direct = agg ? agg.total : 0;
    return '<span class="tcount">' + direct + '</span>';
  }

  function microBar(agg) {
    if (!agg || !agg.total) return '<span class="mbar" title="无实体"></span>';
    var segs = STATUSES.map(function (s) {
      var n = agg.dist[s.id];
      return n ? '<i class="tone-' + s.tone + '" style="flex:' + n + '" title="' + s.label + ' ' + n + '"></i>' : '';
    }).join('');
    return '<span class="mbar">' + segs + '</span>';
  }

  function renderToolbar() {
    var scopeName = state.scopeNodeId === 'root' ? '全部实体'
      : pathText(state.scopeNodeId);
    $('#scope-crumb').textContent = '范围：' + scopeName + '（含子层级）';
    var vis = visibleList().length;
    var sub = entitiesInNode(state.scopeNodeId).length;
    $('#btn-sel-visible').textContent = '选当前筛选结果 (' + vis + ')';
    $('#btn-sel-subtree').textContent = '选子树全部 (' + sub + ')';
    // 状态 chips（全局计数，点击=只显示该状态）
    var distAll = {};
    STATUSES.forEach(function (s) { distAll[s.id] = 0; });
    allEntities().forEach(function (e) { distAll[e.status] += 1; });
    $('#status-chips').innerHTML = STATUSES.map(function (s) {
      var on = !!state.statusFilter[s.id];
      return '<button class="chip tone-' + s.tone + (on ? ' on' : '') + '" data-act="status-chip" data-id="' + s.id + '"' +
        ' aria-pressed="' + on + '" title="' + (on ? '取消筛选' : '只显示') + '「' + s.label + '」">' +
        s.label + ' <b>' + distAll[s.id] + '</b></button>';
    }).join('');
  }

  function renderWarn() {
    var hidden = hiddenSelected();
    var el = $('#warn');
    if (!hidden.length) { el.hidden = true; state.warnListOpen = false; $('#warn-list').hidden = true; return; }
    el.hidden = false;
    $('#warn-text').textContent = '已选 ' + selectedIds().length + ' 项中有 ' + hidden.length +
      ' 项被当前筛选/范围隐藏——批量操作仍会包含它们。';
    var listEl = $('#warn-list');
    listEl.hidden = !state.warnListOpen;
    if (state.warnListOpen) {
      listEl.innerHTML = hidden.map(function (id) {
        var e = ENT_BY_ID[id];
        return '<div class="warn-item"><code>' + esc(id) + '</code> ' + esc(e.name) +
          ' <span class="dim">· ' + esc(pathText(e.categoryId)) + '</span></div>';
      }).join('');
    }
  }

  function renderTable() {
    var list = visibleList();
    var tbody = $('#tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr class="empty-row"><td colspan="8"><div class="empty">' +
        '<div class="empty-title">当前范围内没有匹配的实体</div>' +
        '<div class="dim">调整关键字或状态筛选，或<span class="link" data-act="clear-filters" tabindex="0">清除全部筛选</span></div>' +
        '</div></td></tr>';
    } else {
      tbody.innerHTML = list.map(function (e) {
        var sel = !!state.selection[e.id];
        var open = !!state.detailOpen[e.id];
        var row = '<tr class="ent' + (sel ? ' sel' : '') + '" data-id="' + e.id + '">' +
          '<td class="c-check"><input type="checkbox" data-act="row-check" data-id="' + e.id + '"' +
          (sel ? ' checked' : '') + ' aria-label="选择 ' + esc(e.name) + '"></td>' +
          '<td class="c-code"><code>' + esc(e.id) + '</code></td>' +
          '<td class="c-name"><button class="name-btn" data-act="detail" data-id="' + e.id + '" aria-expanded="' + open + '">' +
          '<span class="chev">' + (open ? '▾' : '▸') + '</span>' + esc(e.name) + '</button></td>' +
          '<td class="c-status">' + statusBadge(e.status) + '</td>' +
          '<td class="c-path">' + esc(pathText(e.categoryId)) + '</td>' +
          '<td class="c-owner">' + esc(e.owner) + '</td>' +
          '<td class="c-tags">' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join('') : '<span class="dim">—</span>') + '</td>' +
          '<td class="c-date">' + esc(e.updatedAt) + '</td></tr>';
        if (open) {
          row += '<tr class="detail"><td></td><td colspan="7"><div class="detail-card">' +
            '<div><b>编码</b><code>' + esc(e.id) + '</code></div>' +
            '<div><b>归属</b>' + esc(pathText(e.categoryId)) + '</div>' +
            '<div><b>状态</b>' + statusBadge(e.status) + '</div>' +
            '<div><b>负责人</b>' + esc(e.owner) + '</div>' +
            '<div><b>标签</b>' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join(' ') : '—') + '</div>' +
            '<div><b>备注</b>' + esc(e.note) + '</div>' +
            '<div><b>更新</b>' + esc(e.updatedAt) + '</div></div></td></tr>';
        }
        return row;
      }).join('');
    }
    // 表头三态复选框
    var visIds = list.map(function (e) { return e.id; });
    var selVis = visIds.filter(function (id) { return state.selection[id]; }).length;
    var head = $('#head-check');
    head.checked = visIds.length > 0 && selVis === visIds.length;
    head.indeterminate = selVis > 0 && selVis < visIds.length;
    $('#sel-summary').textContent = '已选 ' + selectedIds().length + ' · 可见 ' + visIds.length + ' · 范围内 ' + entitiesInNode(state.scopeNodeId).length;
    // 排序指示
    document.querySelectorAll('#thead th[data-sort]').forEach(function (th) {
      var on = th.getAttribute('data-sort') === state.sortKey;
      th.setAttribute('aria-sort', on ? (state.sortDir === 1 ? 'ascending' : 'descending') : 'none');
      var el = th.querySelector('.sort-ind');
      el.textContent = on ? (state.sortDir === 1 ? '▲' : '▼') : '';
    });
  }

  function renderActionbar() {
    var n = selectedIds().length;
    var bar = $('#actionbar');
    bar.hidden = n === 0;
    if (!n) return;
    var hidden = hiddenSelected().length;
    $('#ab-count').innerHTML = '已选 <b>' + n + '</b> 项' +
      (hidden ? ' <span class="ab-hidden">（' + hidden + ' 项当前不可见，仍将包含）</span>' : '');
  }

  function renderStatusbar() {
    var el = $('#receipt');
    if (state.lastOp && !state.lastOp.undone) {
      el.innerHTML = '<span class="rc-ok">✓</span> ' + esc(state.lastOp.receipt) +
        ' <button class="btn btn-mini" data-act="undo">撤销</button>';
    } else if (state.lastOp && state.lastOp.undone) {
      el.innerHTML = '<span class="dim">已撤销：' + esc(state.lastOp.receipt) + '</span>';
    } else {
      el.innerHTML = '<span class="dim">就绪 · 批量操作经逐项预览确认后生效</span>';
    }
    $('#ops-btn').textContent = '操作记录 (' + state.ops.length + ')';
    var panel = $('#ops-panel');
    panel.hidden = !state.opsPanelOpen;
    if (state.opsPanelOpen) {
      panel.innerHTML = state.ops.length
        ? state.ops.slice().reverse().map(function (op) {
          return '<div class="op-item' + (op.undone ? ' undone' : '') + '">' +
            '<span class="op-time">' + esc(op.time) + '</span> ' + esc(op.label) +
            (op.undone ? ' <span class="op-undone">已撤销</span>' : '') + '</div>';
        }).join('')
        : '<div class="dim op-item">暂无操作</div>';
    }
  }

  function renderAll() {
    renderTree();
    renderToolbar();
    renderWarn();
    renderTable();
    renderActionbar();
    renderStatusbar();
  }

  // ---------- 选择集动作（唯一合法入口） ----------
  function addVisible() { visibleList().forEach(function (e) { state.selection[e.id] = true; }); renderAll(); }
  function addSubtree() { entitiesInNode(state.scopeNodeId).forEach(function (e) { state.selection[e.id] = true; }); renderAll(); }
  function clearSel() { state.selection = {}; state.anchor = null; renderAll(); }
  function pruneToVisible() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    selectedIds().forEach(function (id) { if (!vis[id]) delete state.selection[id]; });
    renderAll();
  }

  function shiftRange(currentId, shift) {
    if (!shift || !state.anchor) { state.anchor = currentId; return false; }
    var visIds = visibleList().map(function (e) { return e.id; });
    var a = visIds.indexOf(state.anchor), b = visIds.indexOf(currentId);
    if (a === -1 || b === -1) { state.anchor = currentId; return false; }
    if (a > b) { var t = a; a = b; b = t; }
    for (var i = a; i <= b; i++) state.selection[visIds[i]] = true;
    renderAll();
    return true;
  }

  // ---------- 批量操作引擎 ----------
  var OP_META = {
    'status':     { title: '批量修改状态', need: 'target-status' },
    'move':       { title: '批量移动类别', need: 'target-cat' },
    'tag-add':    { title: '批量添加标签', need: 'tags' },
    'tag-remove': { title: '批量移除标签', need: 'tag' },
    'delete':     { title: '批量删除实体', need: 'confirm-delete' }
  };

  function openPreview(type) {
    var ids = selectedIds();
    if (!ids.length) return;
    state.pending = { type: type, ids: ids, target: '', tags: '', confirmDelete: false };
    renderPreviewModal();
    $('#modal').hidden = false;
    var first = $('#modal').querySelector('select,input[type=text]');
    if (first) first.focus();
  }

  function closePreview() {
    state.pending = null;
    $('#modal').hidden = true;
  }

  function renderPreviewModal() {
    var p = state.pending;
    if (!p) return;
    var meta = OP_META[p.type];
    $('#modal-title').textContent = meta.title;

    // 控制区
    var ctrl = $('#modal-ctrl');
    if (p.type === 'status') {
      ctrl.innerHTML = '<label>目标状态</label><select id="op-target" aria-label="目标状态">' +
        '<option value="">— 选择目标状态 —</option>' +
        STATUSES.map(function (s) {
          return '<option value="' + s.id + '"' + (p.target === s.id ? ' selected' : '') + '>' + s.label + '</option>';
        }).join('') + '</select>';
    } else if (p.type === 'move') {
      var opts = [];
      SEED.categories.forEach(function (c) {
        opts.push('<option value="' + c.id + '"' + (p.target === c.id ? ' selected' : '') + '>' +
          '　'.repeat(c.depth) + esc(c.name) + '（' + esc(CAT_BY_ID[c.domainId].name) + '）</option>');
      });
      ctrl.innerHTML = '<label>目标类别</label><select id="op-target" aria-label="目标类别">' +
        '<option value="">— 选择目标类别 —</option>' + opts.join('') + '</select>';
    } else if (p.type === 'tag-add') {
      ctrl.innerHTML = '<label>新标签（逗号分隔）</label><input type="text" id="op-tags" placeholder="如：待巡检, 核心">' ;
    } else if (p.type === 'tag-remove') {
      var tagSet = {};
      p.ids.forEach(function (id) { ENT_BY_ID[id].tags.forEach(function (t) { tagSet[t] = true; }); });
      var tagOpts = Object.keys(tagSet).map(function (t) {
        return '<option value="' + esc(t) + '"' + (p.target === t ? ' selected' : '') + '>' + esc(t) + '</option>';
      }).join('');
      ctrl.innerHTML = '<label>要移除的标签</label><select id="op-target" aria-label="要移除的标签">' +
        '<option value="">— 选择标签 —</option>' + tagOpts + '</select>';
    } else {
      ctrl.innerHTML = '<label class="danger-label"><input type="checkbox" id="op-confirm-del"> ' +
        '我确认删除以下 <b>' + p.ids.length + '</b> 项（操作后可撤销）</label>';
    }

    // 目标值回填
    var targetSel = $('#op-target');
    if (targetSel) targetSel.addEventListener('change', function () { state.pending.target = this.value; renderPreviewModal(); var s = $('#op-target'); if (s) s.focus(); });
    var tagsInput = $('#op-tags');
    if (tagsInput) {
      tagsInput.value = p.tags;
      tagsInput.addEventListener('input', function () { state.pending.tags = this.value; renderPreviewModal(); var i2 = $('#op-tags'); i2.focus(); i2.setSelectionRange(i2.value.length, i2.value.length); });
    }
    var delChk = $('#op-confirm-del');
    if (delChk) delChk.addEventListener('change', function () { state.pending.confirmDelete = this.checked; renderPreviewModal(); });

    // 受影响集合（预览 = 执行的唯一来源）
    var op = pendingOp();
    var aff = op ? computeAffected(p.ids, op) : { apply: [], noop: p.ids.map(function (id) {
      var e = ENT_BY_ID[id]; return { id: id, name: e.name, path: pathText(e.categoryId), reason: '尚未选择目标' };
    }) };
    state.pending._aff = aff;

    $('#modal-summary').innerHTML =
      '<span class="mchip">已选 <b>' + p.ids.length + '</b> 项</span>' +
      '<span class="mchip ok">将生效 <b>' + aff.apply.length + '</b> 项</span>' +
      (aff.noop.length ? '<span class="mchip dim">跳过（无变更）<b>' + aff.noop.length + '</b> 项</span>' : '');

    var listEl = $('#modal-list');
    var rows = aff.apply.map(function (it) {
      var detail = '';
      if (p.type === 'status') detail = statusBadge(it.before) + ' <span class="arrow">→</span> ' + statusBadge(it.after);
      else if (p.type === 'move') detail = '<span class="dim">' + esc(it.beforePath) + '</span> <span class="arrow">→</span> ' + esc(it.afterPath);
      else if (p.type === 'tag-add') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else if (p.type === 'tag-remove') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else detail = statusBadge(it.before) + ' <span class="arrow">→</span> <span class="badge tone-danger">删除</span>';
      return '<div class="aff-row"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change">' + detail + '</span></div>';
    }).join('');
    var noopRows = aff.noop.map(function (it) {
      return '<div class="aff-row noop"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change dim">' + esc(it.reason) + '</span></div>';
    }).join('');
    listEl.innerHTML =
      (rows ? '<div class="aff-head">将生效（' + aff.apply.length + '）</div>' + rows : '') +
      (noopRows ? '<div class="aff-head dim-head">跳过——无变更（' + aff.noop.length + '）</div>' + noopRows : '') ||
      '<div class="dim aff-row">没有可选实体</div>';

    // 错误/可用性
    var err = validatePending();
    $('#modal-error').textContent = err || '';
    $('#btn-confirm').disabled = !!err;
    $('#btn-confirm').textContent = p.type === 'delete' ? '确认删除 ' + aff.apply.length + ' 项' : '确认执行（' + aff.apply.length + ' 项）';
  }

  function tagsText(tags, highlightDiff) {
    if (!tags || !tags.length) return '<span class="dim">—</span>';
    return tags.map(function (t) { return '<span class="tag' + (highlightDiff ? ' hl' : '') + '">' + esc(t) + '</span>'; }).join(' ');
  }

  function pendingOp() {
    var p = state.pending;
    if (!p) return null;
    if (p.type === 'status' && p.target) return { type: 'status', target: p.target };
    if (p.type === 'move' && p.target) return { type: 'move', target: p.target };
    if (p.type === 'tag-add') {
      var tags = p.tags.split(/[,，]/).map(function (t) { return t.trim(); }).filter(Boolean);
      return tags.length ? { type: 'tag-add', tags: tags } : null;
    }
    if (p.type === 'tag-remove' && p.target) return { type: 'tag-remove', tag: p.target };
    if (p.type === 'delete') return { type: 'delete' };
    return null;
  }

  function validatePending() {
    var p = state.pending;
    if (!p) return '内部错误';
    var op = pendingOp();
    if (!op) {
      if (p.type === 'delete') return '请先勾选确认框';
      return p.type === 'tag-add' ? '请输入至少一个标签' : '请选择目标';
    }
    var aff = computeAffected(p.ids, op);
    if (!aff.apply.length) return '没有可生效的变更（全部所选实体已处于目标状态/位置）';
    if (p.type === 'delete' && !p.confirmDelete) return '请先勾选确认框';
    return '';
  }

  function confirmOp() {
    var p = state.pending;
    if (!p || validatePending()) return;
    var op = pendingOp();
    var aff = computeAffected(p.ids, op); // 再次计算 = 与预览同一函数；此处 aff 与 state.pending._aff 同源
    var time = new Date().toTimeString().slice(0, 8);
    var snapshot = aff.apply.map(function (it) {
      var e = it.e;
      return { id: it.id, status: e.status, categoryId: e.categoryId, tags: e.tags.slice() };
    });
    aff.apply.forEach(function (it) {
      var e = it.e;
      if (op.type === 'status') e.status = op.target;
      else if (op.type === 'move') e.categoryId = op.target;
      else if (op.type === 'tag-add') { op.tags.forEach(function (t) { if (e.tags.indexOf(t) === -1) e.tags.push(t); }); }
      else if (op.type === 'tag-remove') { e.tags = e.tags.filter(function (t) { return t !== op.tag; }); }
      else if (op.type === 'delete') { e._deleted = true; }
    });
    if (op.type === 'delete') {
      SEED.entities = SEED.entities.filter(function (e) { return !e._deleted; });
      aff.apply.forEach(function (it) { delete ENT_BY_ID[it.id]; delete state.selection[it.id]; delete state.detailOpen[it.id]; });
    }
    var label = OP_META[p.type].title;
    var receipt;
    if (op.type === 'status') receipt = '已将 ' + aff.apply.length + ' 项状态改为「' + STATUS_BY_ID[op.target].label + '」';
    else if (op.type === 'move') receipt = '已将 ' + aff.apply.length + ' 项移动到「' + pathText(op.target) + '」';
    else if (op.type === 'tag-add') receipt = '已为 ' + aff.apply.length + ' 项添加标签「' + op.tags.join('、') + '」';
    else if (op.type === 'tag-remove') receipt = '已从 ' + aff.apply.length + ' 项移除标签「' + op.tag + '」';
    else receipt = '已删除 ' + aff.apply.length + ' 项';
    var record = { time: time, label: label + ' ' + p.ids.length + ' 项', receipt: receipt, snapshot: snapshot, undone: false, type: op.type, restore: op.type === 'delete' ? snapshot : null };
    state.ops.push(record);
    state.lastOp = record;
    state.pending = null;
    state.selection = {};
    state.anchor = null;
    $('#modal').hidden = true;
    renderAll();
  }

  function undoLast() {
    var op = state.lastOp;
    if (!op || op.undone) return;
    if (op.type === 'delete') {
      op.snapshot.forEach(function (s) {
        var e = { id: s.id, status: s.status, categoryId: s.categoryId, tags: s.tags, name: s.name, owner: s.owner, note: s.note, updatedAt: s.updatedAt };
        SEED.entities.push(e);
        ENT_BY_ID[s.id] = e;
      });
      // delete 快照需含全部字段：见 makeSnapshot 增强
    } else {
      op.snapshot.forEach(function (s) {
        var e = ENT_BY_ID[s.id];
        if (!e) return;
        e.status = s.status; e.categoryId = s.categoryId; e.tags = s.tags.slice();
      });
    }
    op.undone = true;
    state.lastOp = null;
    renderAll();
  }

  // 删除快照增强：补全恢复所需字段
  var _origCompute = computeAffected;
  computeAffected = function (ids, op) {
    var r = _origCompute(ids, op);
    if (op && op.type === 'delete') {
      r.apply.forEach(function (it) {
        var e = it.e;
        it.full = { id: e.id, status: e.status, categoryId: e.categoryId, tags: e.tags.slice(), name: e.name, owner: e.owner, note: e.note, updatedAt: e.updatedAt };
      });
    }
    return r;
  };

  // ---------- 事件 ----------
  function wire() {
    // 树：scope / toggle（点击与键盘）
    $('#tree').addEventListener('click', function (ev) {
      var row = ev.target.closest('.trow');
      if (!row) return;
      treeAct(row);
    });
    $('#tree').addEventListener('keydown', function (ev) {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      var row = ev.target.closest('.trow');
      if (!row) return;
      ev.preventDefault();
      treeAct(row);
    });

    // 工具栏
    $('#search').addEventListener('input', function () { state.query = this.value; renderAll(); });
    $('#status-chips').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act="status-chip"]');
      if (!b) return;
      var id = b.getAttribute('data-id');
      if (state.statusFilter[id]) delete state.statusFilter[id]; else state.statusFilter[id] = true;
      renderAll();
    });
    $('#btn-sel-visible').addEventListener('click', addVisible);
    $('#btn-sel-subtree').addEventListener('click', addSubtree);
    $('#btn-clear-filters').addEventListener('click', clearFilters);

    // 警示条
    $('#warn').addEventListener('click', function (ev) {
      var act = ev.target.getAttribute('data-act') || (ev.target.closest('[data-act]') && ev.target.closest('[data-act]').getAttribute('data-act'));
      if (act === 'keep-visible') pruneToVisible();
      else if (act === 'toggle-list') { state.warnListOpen = !state.warnListOpen; renderWarn(); }
    });

    // 表格
    $('#thead').addEventListener('click', function (ev) {
      var th = ev.target.closest('th[data-sort]');
      if (!th) return;
      var k = th.getAttribute('data-sort');
      if (state.sortKey === k) state.sortDir *= -1; else { state.sortKey = k; state.sortDir = 1; }
      renderAll();
    });
    var tbody = $('#tbody');
    tbody.addEventListener('click', function (ev) {
      var clear = ev.target.closest('[data-act="clear-filters"]');
      if (clear) { clearFilters(); return; }
      var nameBtn = ev.target.closest('[data-act="detail"]');
      if (nameBtn) {
        var id = nameBtn.getAttribute('data-id');
        state.detailOpen[id] = !state.detailOpen[id];
        renderTable();
        return;
      }
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (chk) {
        var id2 = chk.getAttribute('data-id');
        if (ev.shiftKey) { shiftRange(id2, true); }
        state.anchor = id2;
        return; // change 事件负责同步选择集
      }
    });
    tbody.addEventListener('change', function (ev) {
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (!chk) return;
      var id = chk.getAttribute('data-id');
      if (chk.checked) state.selection[id] = true; else delete state.selection[id];
      state.anchor = id;
      renderAll();
    });
    $('#head-check').addEventListener('click', function () {
      var list = visibleList();
      var allSel = list.length && list.every(function (e) { return state.selection[e.id]; });
      if (allSel) list.forEach(function (e) { delete state.selection[e.id]; });
      else list.forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
    });

    // 操作条
    $('#actionbar').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-op]');
      if (!b) return;
      openPreview(b.getAttribute('data-op'));
    });
    $('#btn-ab-clear').addEventListener('click', clearSel);

    // 模态
    $('#btn-cancel').addEventListener('click', closePreview);
    $('#btn-confirm').addEventListener('click', confirmOp);
    $('#modal').addEventListener('click', function (ev) { if (ev.target === $('#modal')) closePreview(); });

    // 状态栏
    $('#statusbar').addEventListener('click', function (ev) {
      var act = ev.target.closest('[data-act]');
      if (!act) return;
      if (act.getAttribute('data-act') === 'undo') undoLast();
      if (act.getAttribute('data-act') === 'toggle-ops') { state.opsPanelOpen = !state.opsPanelOpen; renderStatusbar(); }
    });

    // 键盘契约
    document.addEventListener('keydown', function (ev) {
      if (ev.key === '/' && !/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)) {
        ev.preventDefault(); $('#search').focus();
      }
      if (ev.key === 'Escape' && state.pending) closePreview();
    });

    window.addEventListener('error', function (e) {
      var el = $('#errbanner');
      el.hidden = false;
      el.textContent = '运行错误：' + (e.message || '未知错误');
    });
  }

  function treeAct(row) {
    var id = row.getAttribute('data-id');
    var act = row.getAttribute('data-act');
    if (act === 'toggle' && (CHILDREN[id] || SEED.domains.some(function (d) { return d.id === id; }))) {
      state.expanded[id] = !state.expanded[id];
      renderAll();
    } else {
      state.scopeNodeId = id;
      renderAll();
    }
  }

  function clearFilters() {
    state.query = '';
    state.statusFilter = {};
    state.scopeNodeId = 'root';
    $('#search').value = '';
    renderAll();
  }

  // ---------- 演示场景（供自动化截图取证；不影响正常使用） ----------
  function runScene() {
    var m = /scene=(\w+)/.exec(location.search);
    if (!m) return;
    var scene = m[1];
    if (scene === 'selected') {
      // 选中「产线设备」子树全部，再筛选「在用」→ 制造隐藏已选警示 + 操作条
      entitiesInNode('c3').forEach(function (e) { state.selection[e.id] = true; });
      state.statusFilter = { active: true };
      renderAll();
    } else if (scene === 'preview') {
      entitiesInNode('c11').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('status');
      state.pending.target = 'disabled';
      renderPreviewModal();
    } else if (scene === 'delete') {
      entitiesInNode('c34').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('delete');
    }
  }

  // ---------- 启动：同步就绪，无加载态 ----------
  wire();
  renderAll();
  runScene();
})();

tool_use_result.content:
/* cell-j01-s01 实体目录管理台 — 应用核心
 * 架构：单一数据源（内存实体数组）+ 派生渲染；
 * 状态归属：selection（选择集）/ query（筛选器）/ mode（预览模态）/ viewport（树展开）四类状态各有唯一属主。
 * 零误伤契约：computeAffected() 是预览与执行的唯一共同来源——确认列表与实际作用集合逐 id 一致。 */
(function () {
  'use strict';

  var SEED = window.SEED;
  var STATUSES = SEED.statuses;
  var STATUS_BY_ID = {};
  STATUSES.forEach(function (s) { STATUS_BY_ID[s.id] = s; });

  // ---------- 索引 ----------
  var CAT_BY_ID = {};
  SEED.categories.forEach(function (c) { CAT_BY_ID[c.id] = c; });
  var CHILDREN = {};
  SEED.categories.forEach(function (c) {
    if (c.parentId) { (CHILDREN[c.parentId] = CHILDREN[c.parentId] || []).push(c); }
  });
  var DOMAIN_CATS = {};
  SEED.categories.forEach(function (c) {
    if (!c.parentId) { (DOMAIN_CATS[c.domainId] = DOMAIN_CATS[c.domainId] || []).push(c); }
  });
  var ENT_BY_ID = {};
  SEED.entities.forEach(function (e) { ENT_BY_ID[e.id] = e; });

  // ---------- 状态（各有唯一属主） ----------
  var state = {
    // query —— 筛选器：只决定可见行，永不触碰 selection
    scopeNodeId: 'root',
    query: '',
    statusFilter: {},        // {statusId:true}
    sortKey: 'id',
    sortDir: 1,
    // selection —— 选择集：仅 行复选 / 范围全选 / 清空 / 仅保留可见 四种显式动作可变
    selection: {},           // {entityId:true}
    // viewport —— 树展开状态
    expanded: { root: true },
    // mode —— 预览确认模态（暂存待执行操作）
    pending: null,
    // 操作记录
    ops: [],
    lastOp: null,
    // 交互辅助
    anchor: null,            // shift 范围选择锚点
    detailOpen: {},          // 行内展开
    warnListOpen: false,
    opsPanelOpen: false
  };

  SEED.domains.forEach(function (d) { state.expanded[d.id] = true; });
  SEED.categories.forEach(function (c) { if (c.depth <= 1) state.expanded[c.id] = true; });

  // ---------- 纯派生 ----------
  function allEntities() { return SEED.entities; }

  function catPath(catId) {
    var parts = [], c = CAT_BY_ID[catId];
    while (c) { parts.unshift(c.name); c = c.parentId ? CAT_BY_ID[c.parentId] : null; }
    return parts;
  }
  function pathText(catId) { return catPath(catId).join(' / '); }
  function statusOf(e) { return STATUS_BY_ID[e.status]; }

  function subtreeCatIds(nodeId) {
    if (nodeId === 'root') return SEED.categories.map(function (c) { return c.id; });
    var out = [nodeId], queue = [nodeId];
    while (queue.length) {
      var cur = queue.shift();
      (CHILDREN[cur] || []).forEach(function (ch) { out.push(ch.id); queue.push(ch.id); });
    }
    return out;
  }

  function entitiesInNode(nodeId) {
    var ids = subtreeCatIds(nodeId), set = {};
    ids.forEach(function (id) { set[id] = true; });
    return allEntities().filter(function (e) { return set[e.categoryId]; });
  }

  function visibleList() {
    var q = state.query.trim().toLowerCase();
    var scopeIds = subtreeCatIds(state.scopeNodeId), scopeSet = {};
    scopeIds.forEach(function (id) { scopeSet[id] = true; });
    var list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (state.statusFilter[e.status]) {
        // 状态筛选语义：勾选的状态=排除该状态（筛选chip显示为「隐藏 xx」）？
        // —— 采用「显示所选状态」的常规语义：见下方判断
      }
      return true;
    });
    // 状态筛选：未勾选任何状态 = 全部显示；有勾选 = 只显示勾选状态
    var active = STATUSES.some(function (s) { return state.statusFilter[s.id]; });
    if (active) list = list.filter(function (e) { return state.statusFilter[e.status]; });
    if (q) {
      list = list.filter(function (e) {
        return (e.id + ' ' + e.name + ' ' + e.owner + ' ' + e.tags.join(' ') + ' ' + pathText(e.categoryId))
          .toLowerCase().indexOf(q) !== -1;
      });
    }
    var k = state.sortKey, dir = state.sortDir;
    list.sort(function (a, b) {
      var va, vb;
      if (k === 'status') { va = statusOf(a).label; vb = statusOf(b).label; }
      else if (k === 'path') { va = pathText(a.categoryId); vb = pathText(b.categoryId); }
      else { va = a[k]; vb = b[k]; }
      return va < vb ? -dir : va > vb ? dir : (a.id < b.id ? -1 : 1);
    });
    return list;
  }

  // 节点聚合：直接计数 / 累计计数 / 状态分布（树、表格、状态栏三处同源）
  function nodeAgg(nodeId) {
    var list = entitiesInNode(nodeId);
    var dist = {};
    STATUSES.forEach(function (s) { dist[s.id] = 0; });
    list.forEach(function (e) { dist[e.status] += 1; });
    return { total: list.length, dist: dist };
  }

  function selectedIds() {
    return Object.keys(state.selection);
  }
  function hiddenSelected() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    return selectedIds().filter(function (id) { return !vis[id]; });
  }

  // ---------- 零误伤核心：预览与执行共用同一计算 ----------
  // 返回 {apply:[{id,before,after}], noop:[{id,reason}]}
  function computeAffected(ids, op) {
    var apply = [], noop = [];
    ids.forEach(function (id) {
      var e = ENT_BY_ID[id];
      var item = { id: id, name: e.name, path: pathText(e.categoryId), e: e };
      if (op.type === 'status') {
        if (e.status === op.target) { item.reason = '已是「' + statusOf(e).label + '」'; noop.push(item); return; }
        item.before = e.status; item.after = op.target;
      } else if (op.type === 'move') {
        if (e.categoryId === op.target) { item.reason = '已在该类别'; noop.push(item); return; }
        item.beforePath = pathText(e.categoryId); item.afterPath = pathText(op.target);
      } else if (op.type === 'tag-add') {
        var add = op.tags.filter(function (t) { return e.tags.indexOf(t) === -1; });
        if (!add.length) { item.reason = '已含全部目标标签'; noop.push(item); return; }
        item.beforeTags = e.tags.slice(); item.afterTags = e.tags.concat(add);
      } else if (op.type === 'tag-remove') {
        if (e.tags.indexOf(op.tag) === -1) { item.reason = '不含标签「' + op.tag + '」'; noop.push(item); return; }
        item.beforeTags = e.tags.slice();
        item.afterTags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        item.before = e.status;
      }
      apply.push(item);
    });
    return { apply: apply, noop: noop };
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // ---------- 渲染 ----------
  var $ = function (sel) { return document.querySelector(sel); };

  function statusBadge(sid, extra) {
    var s = STATUS_BY_ID[sid];
    return '<span class="badge tone-' + s.tone + (extra ? ' ' + extra : '') + '">' + s.label + '</span>';
  }

  function renderTree() {
    var host = $('#tree');
    var html = treeNode('root', '全部实体', null, 0);
    SEED.domains.forEach(function (d) {
      var kids = DOMAIN_CATS[d.id] || [];
      var inner = kids.map(function (c) { return catNode(c, 1); }).join('');
      html += domainNode(d, inner);
    });
    host.innerHTML = html;
  }

  function domainNode(d, inner) {
    var agg = nodeAgg(d.id);
    var open = !!state.expanded[d.id];
    return '<div class="tnode depth-0' + (state.scopeNodeId === d.id ? ' scoped' : '') + '" data-node="' + d.id + '">' +
      '<div class="trow" role="treeitem" aria-expanded="' + open + '" tabindex="0" data-act="toggle" data-id="' + d.id + '">' +
      '<span class="caret' + (open ? ' open' : '') + '">▸</span>' +
      '<span class="tname">' + esc(d.name) + '</span>' + countsHtml(agg) + microBar(agg) + '</div>' +
      (open ? '<div class="tkids">' + inner + '</div>' : '') +
      '</div>';
  }

  function catNode(c, depth) {
    var agg = nodeAgg(c.id);
    var kids = CHILDREN[c.id] || [];
    var open = !!state.expanded[c.id];
    var row = '<div class="trow' + (state.scopeNodeId === c.id ? ' scoped' : '') + '" role="treeitem" tabindex="0"' +
      (kids.length ? ' aria-expanded="' + open + '"' : '') +
      ' data-act="' + (kids.length ? 'toggle' : 'scope') + '" data-id="' + c.id + '">' +
      (kids.length ? '<span class="caret' + (open ? ' open' : '') + '">▸</span>' : '<span class="caret leaf"></span>') +
      '<span class="tname">' + esc(c.name) + '</span>' + countsHtml(agg) + microBar(agg) + '</div>';
    var childHtml = kids.length && open ? '<div class="tkids">' + kids.map(function (ch) { return catNode(ch, depth + 1); }).join('') + '</div>' : '';
    return '<div class="tnode depth-' + depth + '">' + row + childHtml + '</div>';
  }

  function treeNode(id, name, aggIgnored, depth) {
    var agg = nodeAgg(id === 'root' ? 'root' : id);
    var list = id === 'root' ? { total: agg.total } : agg;
    return '<div class="tnode depth-0' + (state.scopeNodeId === 'root' ? ' scoped' : '') + '" data-node="root">' +
      '<div class="trow" role="treeitem" tabindex="0" data-act="scope" data-id="root">' +
      '<span class="caret leaf"></span><span class="tname">' + esc(name) + '</span>' +
      countsHtml({ total: agg.total }) + microBar(agg) + '</div></div>';
  }

  function countsHtml(agg) {
    var direct = agg ? agg.total : 0;
    return '<span class="tcount">' + direct + '</span>';
  }

  function microBar(agg) {
    if (!agg || !agg.total) return '<span class="mbar" title="无实体"></span>';
    var segs = STATUSES.map(function (s) {
      var n = agg.dist[s.id];
      return n ? '<i class="tone-' + s.tone + '" style="flex:' + n + '" title="' + s.label + ' ' + n + '"></i>' : '';
    }).join('');
    return '<span class="mbar">' + segs + '</span>';
  }

  function renderToolbar() {
    var scopeName = state.scopeNodeId === 'root' ? '全部实体'
      : pathText(state.scopeNodeId);
    $('#scope-crumb').textContent = '范围：' + scopeName + '（含子层级）';
    var vis = visibleList().length;
    var sub = entitiesInNode(state.scopeNodeId).length;
    $('#btn-sel-visible').textContent = '选当前筛选结果 (' + vis + ')';
    $('#btn-sel-subtree').textContent = '选子树全部 (' + sub + ')';
    // 状态 chips（全局计数，点击=只显示该状态）
    var distAll = {};
    STATUSES.forEach(function (s) { distAll[s.id] = 0; });
    allEntities().forEach(function (e) { distAll[e.status] += 1; });
    $('#status-chips').innerHTML = STATUSES.map(function (s) {
      var on = !!state.statusFilter[s.id];
      return '<button class="chip tone-' + s.tone + (on ? ' on' : '') + '" data-act="status-chip" data-id="' + s.id + '"' +
        ' aria-pressed="' + on + '" title="' + (on ? '取消筛选' : '只显示') + '「' + s.label + '」">' +
        s.label + ' <b>' + distAll[s.id] + '</b></button>';
    }).join('');
  }

  function renderWarn() {
    var hidden = hiddenSelected();
    var el = $('#warn');
    if (!hidden.length) { el.hidden = true; state.warnListOpen = false; $('#warn-list').hidden = true; return; }
    el.hidden = false;
    $('#warn-text').textContent = '已选 ' + selectedIds().length + ' 项中有 ' + hidden.length +
      ' 项被当前筛选/范围隐藏——批量操作仍会包含它们。';
    var listEl = $('#warn-list');
    listEl.hidden = !state.warnListOpen;
    if (state.warnListOpen) {
      listEl.innerHTML = hidden.map(function (id) {
        var e = ENT_BY_ID[id];
        return '<div class="warn-item"><code>' + esc(id) + '</code> ' + esc(e.name) +
          ' <span class="dim">· ' + esc(pathText(e.categoryId)) + '</span></div>';
      }).join('');
    }
  }

  function renderTable() {
    var list = visibleList();
    var tbody = $('#tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr class="empty-row"><td colspan="8"><div class="empty">' +
        '<div class="empty-title">当前范围内没有匹配的实体</div>' +
        '<div class="dim">调整关键字或状态筛选，或<span class="link" data-act="clear-filters" tabindex="0">清除全部筛选</span></div>' +
        '</div></td></tr>';
    } else {
      tbody.innerHTML = list.map(function (e) {
        var sel = !!state.selection[e.id];
        var open = !!state.detailOpen[e.id];
        var row = '<tr class="ent' + (sel ? ' sel' : '') + '" data-id="' + e.id + '">' +
          '<td class="c-check"><input type="checkbox" data-act="row-check" data-id="' + e.id + '"' +
          (sel ? ' checked' : '') + ' aria-label="选择 ' + esc(e.name) + '"></td>' +
          '<td class="c-code"><code>' + esc(e.id) + '</code></td>' +
          '<td class="c-name"><button class="name-btn" data-act="detail" data-id="' + e.id + '" aria-expanded="' + open + '">' +
          '<span class="chev">' + (open ? '▾' : '▸') + '</span>' + esc(e.name) + '</button></td>' +
          '<td class="c-status">' + statusBadge(e.status) + '</td>' +
          '<td class="c-path">' + esc(pathText(e.categoryId)) + '</td>' +
          '<td class="c-owner">' + esc(e.owner) + '</td>' +
          '<td class="c-tags">' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join('') : '<span class="dim">—</span>') + '</td>' +
          '<td class="c-date">' + esc(e.updatedAt) + '</td></tr>';
        if (open) {
          row += '<tr class="detail"><td></td><td colspan="7"><div class="detail-card">' +
            '<div><b>编码</b><code>' + esc(e.id) + '</code></div>' +
            '<div><b>归属</b>' + esc(pathText(e.categoryId)) + '</div>' +
            '<div><b>状态</b>' + statusBadge(e.status) + '</div>' +
            '<div><b>负责人</b>' + esc(e.owner) + '</div>' +
            '<div><b>标签</b>' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join(' ') : '—') + '</div>' +
            '<div><b>备注</b>' + esc(e.note) + '</div>' +
            '<div><b>更新</b>' + esc(e.updatedAt) + '</div></div></td></tr>';
        }
        return row;
      }).join('');
    }
    // 表头三态复选框
    var visIds = list.map(function (e) { return e.id; });
    var selVis = visIds.filter(function (id) { return state.selection[id]; }).length;
    var head = $('#head-check');
    head.checked = visIds.length > 0 && selVis === visIds.length;
    head.indeterminate = selVis > 0 && selVis < visIds.length;
    $('#sel-summary').textContent = '已选 ' + selectedIds().length + ' · 可见 ' + visIds.length + ' · 范围内 ' + entitiesInNode(state.scopeNodeId).length;
    // 排序指示
    document.querySelectorAll('#thead th[data-sort]').forEach(function (th) {
      var on = th.getAttribute('data-sort') === state.sortKey;
      th.setAttribute('aria-sort', on ? (state.sortDir === 1 ? 'ascending' : 'descending') : 'none');
      var el = th.querySelector('.sort-ind');
      el.textContent = on ? (state.sortDir === 1 ? '▲' : '▼') : '';
    });
  }

  function renderActionbar() {
    var n = selectedIds().length;
    var bar = $('#actionbar');
    bar.hidden = n === 0;
    if (!n) return;
    var hidden = hiddenSelected().length;
    $('#ab-count').innerHTML = '已选 <b>' + n + '</b> 项' +
      (hidden ? ' <span class="ab-hidden">（' + hidden + ' 项当前不可见，仍将包含）</span>' : '');
  }

  function renderStatusbar() {
    var el = $('#receipt');
    if (state.lastOp && !state.lastOp.undone) {
      el.innerHTML = '<span class="rc-ok">✓</span> ' + esc(state.lastOp.receipt) +
        ' <button class="btn btn-mini" data-act="undo">撤销</button>';
    } else if (state.lastOp && state.lastOp.undone) {
      el.innerHTML = '<span class="dim">已撤销：' + esc(state.lastOp.receipt) + '</span>';
    } else {
      el.innerHTML = '<span class="dim">就绪 · 批量操作经逐项预览确认后生效</span>';
    }
    $('#ops-btn').textContent = '操作记录 (' + state.ops.length + ')';
    var panel = $('#ops-panel');
    panel.hidden = !state.opsPanelOpen;
    if (state.opsPanelOpen) {
      panel.innerHTML = state.ops.length
        ? state.ops.slice().reverse().map(function (op) {
          return '<div class="op-item' + (op.undone ? ' undone' : '') + '">' +
            '<span class="op-time">' + esc(op.time) + '</span> ' + esc(op.label) +
            (op.undone ? ' <span class="op-undone">已撤销</span>' : '') + '</div>';
        }).join('')
        : '<div class="dim op-item">暂无操作</div>';
    }
  }

  function renderAll() {
    renderTree();
    renderToolbar();
    renderWarn();
    renderTable();
    renderActionbar();
    renderStatusbar();
  }

  // ---------- 选择集动作（唯一合法入口） ----------
  function addVisible() { visibleList().forEach(function (e) { state.selection[e.id] = true; }); renderAll(); }
  function addSubtree() { entitiesInNode(state.scopeNodeId).forEach(function (e) { state.selection[e.id] = true; }); renderAll(); }
  function clearSel() { state.selection = {}; state.anchor = null; renderAll(); }
  function pruneToVisible() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    selectedIds().forEach(function (id) { if (!vis[id]) delete state.selection[id]; });
    renderAll();
  }

  function shiftRange(currentId, shift) {
    if (!shift || !state.anchor) { state.anchor = currentId; return false; }
    var visIds = visibleList().map(function (e) { return e.id; });
    var a = visIds.indexOf(state.anchor), b = visIds.indexOf(currentId);
    if (a === -1 || b === -1) { state.anchor = currentId; return false; }
    if (a > b) { var t = a; a = b; b = t; }
    for (var i = a; i <= b; i++) state.selection[visIds[i]] = true;
    renderAll();
    return true;
  }

  // ---------- 批量操作引擎 ----------
  var OP_META = {
    'status':     { title: '批量修改状态', need: 'target-status' },
    'move':       { title: '批量移动类别', need: 'target-cat' },
    'tag-add':    { title: '批量添加标签', need: 'tags' },
    'tag-remove': { title: '批量移除标签', need: 'tag' },
    'delete':     { title: '批量删除实体', need: 'confirm-delete' }
  };

  function openPreview(type) {
    var ids = selectedIds();
    if (!ids.length) return;
    state.pending = { type: type, ids: ids, target: '', tags: '', confirmDelete: false };
    renderPreviewModal();
    $('#modal').hidden = false;
    var first = $('#modal').querySelector('select,input[type=text]');
    if (first) first.focus();
  }

  function closePreview() {
    state.pending = null;
    $('#modal').hidden = true;
  }

  function renderPreviewModal() {
    var p = state.pending;
    if (!p) return;
    var meta = OP_META[p.type];
    $('#modal-title').textContent = meta.title;

    // 控制区
    var ctrl = $('#modal-ctrl');
    if (p.type === 'status') {
      ctrl.innerHTML = '<label>目标状态</label><select id="op-target" aria-label="目标状态">' +
        '<option value="">— 选择目标状态 —</option>' +
        STATUSES.map(function (s) {
          return '<option value="' + s.id + '"' + (p.target === s.id ? ' selected' : '') + '>' + s.label + '</option>';
        }).join('') + '</select>';
    } else if (p.type === 'move') {
      var opts = [];
      SEED.categories.forEach(function (c) {
        opts.push('<option value="' + c.id + '"' + (p.target === c.id ? ' selected' : '') + '>' +
          '　'.repeat(c.depth) + esc(c.name) + '（' + esc(CAT_BY_ID[c.domainId].name) + '）</option>');
      });
      ctrl.innerHTML = '<label>目标类别</label><select id="op-target" aria-label="目标类别">' +
        '<option value="">— 选择目标类别 —</option>' + opts.join('') + '</select>';
    } else if (p.type === 'tag-add') {
      ctrl.innerHTML = '<label>新标签（逗号分隔）</label><input type="text" id="op-tags" placeholder="如：待巡检, 核心">' ;
    } else if (p.type === 'tag-remove') {
      var tagSet = {};
      p.ids.forEach(function (id) { ENT_BY_ID[id].tags.forEach(function (t) { tagSet[t] = true; }); });
      var tagOpts = Object.keys(tagSet).map(function (t) {
        return '<option value="' + esc(t) + '"' + (p.target === t ? ' selected' : '') + '>' + esc(t) + '</option>';
      }).join('');
      ctrl.innerHTML = '<label>要移除的标签</label><select id="op-target" aria-label="要移除的标签">' +
        '<option value="">— 选择标签 —</option>' + tagOpts + '</select>';
    } else {
      ctrl.innerHTML = '<label class="danger-label"><input type="checkbox" id="op-confirm-del"> ' +
        '我确认删除以下 <b>' + p.ids.length + '</b> 项（操作后可撤销）</label>';
    }

    // 目标值回填
    var targetSel = $('#op-target');
    if (targetSel) targetSel.addEventListener('change', function () { state.pending.target = this.value; renderPreviewModal(); var s = $('#op-target'); if (s) s.focus(); });
    var tagsInput = $('#op-tags');
    if (tagsInput) {
      tagsInput.value = p.tags;
      tagsInput.addEventListener('input', function () { state.pending.tags = this.value; renderPreviewModal(); var i2 = $('#op-tags'); i2.focus(); i2.setSelectionRange(i2.value.length, i2.value.length); });
    }
    var delChk = $('#op-confirm-del');
    if (delChk) delChk.addEventListener('change', function () { state.pending.confirmDelete = this.checked; renderPreviewModal(); });

    // 受影响集合（预览 = 执行的唯一来源）
    var op = pendingOp();
    var aff = op ? computeAffected(p.ids, op) : { apply: [], noop: p.ids.map(function (id) {
      var e = ENT_BY_ID[id]; return { id: id, name: e.name, path: pathText(e.categoryId), reason: '尚未选择目标' };
    }) };
    state.pending._aff = aff;

    $('#modal-summary').innerHTML =
      '<span class="mchip">已选 <b>' + p.ids.length + '</b> 项</span>' +
      '<span class="mchip ok">将生效 <b>' + aff.apply.length + '</b> 项</span>' +
      (aff.noop.length ? '<span class="mchip dim">跳过（无变更）<b>' + aff.noop.length + '</b> 项</span>' : '');

    var listEl = $('#modal-list');
    var rows = aff.apply.map(function (it) {
      var detail = '';
      if (p.type === 'status') detail = statusBadge(it.before) + ' <span class="arrow">→</span> ' + statusBadge(it.after);
      else if (p.type === 'move') detail = '<span class="dim">' + esc(it.beforePath) + '</span> <span class="arrow">→</span> ' + esc(it.afterPath);
      else if (p.type === 'tag-add') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else if (p.type === 'tag-remove') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else detail = statusBadge(it.before) + ' <span class="arrow">→</span> <span class="badge tone-danger">删除</span>';
      return '<div class="aff-row"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change">' + detail + '</span></div>';
    }).join('');
    var noopRows = aff.noop.map(function (it) {
      return '<div class="aff-row noop"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change dim">' + esc(it.reason) + '</span></div>';
    }).join('');
    listEl.innerHTML =
      (rows ? '<div class="aff-head">将生效（' + aff.apply.length + '）</div>' + rows : '') +
      (noopRows ? '<div class="aff-head dim-head">跳过——无变更（' + aff.noop.length + '）</div>' + noopRows : '') ||
      '<div class="dim aff-row">没有可选实体</div>';

    // 错误/可用性
    var err = validatePending();
    $('#modal-error').textContent = err || '';
    $('#btn-confirm').disabled = !!err;
    $('#btn-confirm').textContent = p.type === 'delete' ? '确认删除 ' + aff.apply.length + ' 项' : '确认执行（' + aff.apply.length + ' 项）';
  }

  function tagsText(tags, highlightDiff) {
    if (!tags || !tags.length) return '<span class="dim">—</span>';
    return tags.map(function (t) { return '<span class="tag' + (highlightDiff ? ' hl' : '') + '">' + esc(t) + '</span>'; }).join(' ');
  }

  function pendingOp() {
    var p = state.pending;
    if (!p) return null;
    if (p.type === 'status' && p.target) return { type: 'status', target: p.target };
    if (p.type === 'move' && p.target) return { type: 'move', target: p.target };
    if (p.type === 'tag-add') {
      var tags = p.tags.split(/[,，]/).map(function (t) { return t.trim(); }).filter(Boolean);
      return tags.length ? { type: 'tag-add', tags: tags } : null;
    }
    if (p.type === 'tag-remove' && p.target) return { type: 'tag-remove', tag: p.target };
    if (p.type === 'delete') return { type: 'delete' };
    return null;
  }

  function validatePending() {
    var p = state.pending;
    if (!p) return '内部错误';
    var op = pendingOp();
    if (!op) {
      if (p.type === 'delete') return '请先勾选确认框';
      return p.type === 'tag-add' ? '请输入至少一个标签' : '请选择目标';
    }
    var aff = computeAffected(p.ids, op);
    if (!aff.apply.length) return '没有可生效的变更（全部所选实体已处于目标状态/位置）';
    if (p.type === 'delete' && !p.confirmDelete) return '请先勾选确认框';
    return '';
  }

  function confirmOp() {
    var p = state.pending;
    if (!p || validatePending()) return;
    var op = pendingOp();
    var aff = computeAffected(p.ids, op); // 再次计算 = 与预览同一函数；此处 aff 与 state.pending._aff 同源
    var time = new Date().toTimeString().slice(0, 8);
    var snapshot = aff.apply.map(function (it) {
      var e = it.e;
      return { id: it.id, status: e.status, categoryId: e.categoryId, tags: e.tags.slice() };
    });
    aff.apply.forEach(function (it) {
      var e = it.e;
      if (op.type === 'status') e.status = op.target;
      else if (op.type === 'move') e.categoryId = op.target;
      else if (op.type === 'tag-add') { op.tags.forEach(function (t) { if (e.tags.indexOf(t) === -1) e.tags.push(t); }); }
      else if (op.type === 'tag-remove') { e.tags = e.tags.filter(function (t) { return t !== op.tag; }); }
      else if (op.type === 'delete') { e._deleted = true; }
    });
    if (op.type === 'delete') {
      SEED.entities = SEED.entities.filter(function (e) { return !e._deleted; });
      aff.apply.forEach(function (it) { delete ENT_BY_ID[it.id]; delete state.selection[it.id]; delete state.detailOpen[it.id]; });
    }
    var label = OP_META[p.type].title;
    var receipt;
    if (op.type === 'status') receipt = '已将 ' + aff.apply.length + ' 项状态改为「' + STATUS_BY_ID[op.target].label + '」';
    else if (op.type === 'move') receipt = '已将 ' + aff.apply.length + ' 项移动到「' + pathText(op.target) + '」';
    else if (op.type === 'tag-add') receipt = '已为 ' + aff.apply.length + ' 项添加标签「' + op.tags.join('、') + '」';
    else if (op.type === 'tag-remove') receipt = '已从 ' + aff.apply.length + ' 项移除标签「' + op.tag + '」';
    else receipt = '已删除 ' + aff.apply.length + ' 项';
    var record = { time: time, label: label + ' ' + p.ids.length + ' 项', receipt: receipt, snapshot: snapshot, undone: false, type: op.type, restore: op.type === 'delete' ? snapshot : null };
    state.ops.push(record);
    state.lastOp = record;
    state.pending = null;
    state.selection = {};
    state.anchor = null;
    $('#modal').hidden = true;
    renderAll();
  }

  function undoLast() {
    var op = state.lastOp;
    if (!op || op.undone) return;
    if (op.type === 'delete') {
      op.snapshot.forEach(function (s) {
        var e = { id: s.id, status: s.status, categoryId: s.categoryId, tags: s.tags, name: s.name, owner: s.owner, note: s.note, updatedAt: s.updatedAt };
        SEED.entities.push(e);
        ENT_BY_ID[s.id] = e;
      });
      // delete 快照需含全部字段：见 makeSnapshot 增强
    } else {
      op.snapshot.forEach(function (s) {
        var e = ENT_BY_ID[s.id];
        if (!e) return;
        e.status = s.status; e.categoryId = s.categoryId; e.tags = s.tags.slice();
      });
    }
    op.undone = true;
    state.lastOp = null;
    renderAll();
  }

  // 删除快照增强：补全恢复所需字段
  var _origCompute = computeAffected;
  computeAffected = function (ids, op) {
    var r = _origCompute(ids, op);
    if (op && op.type === 'delete') {
      r.apply.forEach(function (it) {
        var e = it.e;
        it.full = { id: e.id, status: e.status, categoryId: e.categoryId, tags: e.tags.slice(), name: e.name, owner: e.owner, note: e.note, updatedAt: e.updatedAt };
      });
    }
    return r;
  };

  // ---------- 事件 ----------
  function wire() {
    // 树：scope / toggle（点击与键盘）
    $('#tree').addEventListener('click', function (ev) {
      var row = ev.target.closest('.trow');
      if (!row) return;
      treeAct(row);
    });
    $('#tree').addEventListener('keydown', function (ev) {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      var row = ev.target.closest('.trow');
      if (!row) return;
      ev.preventDefault();
      treeAct(row);
    });

    // 工具栏
    $('#search').addEventListener('input', function () { state.query = this.value; renderAll(); });
    $('#status-chips').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act="status-chip"]');
      if (!b) return;
      var id = b.getAttribute('data-id');
      if (state.statusFilter[id]) delete state.statusFilter[id]; else state.statusFilter[id] = true;
      renderAll();
    });
    $('#btn-sel-visible').addEventListener('click', addVisible);
    $('#btn-sel-subtree').addEventListener('click', addSubtree);
    $('#btn-clear-filters').addEventListener('click', clearFilters);

    // 警示条
    $('#warn').addEventListener('click', function (ev) {
      var act = ev.target.getAttribute('data-act') || (ev.target.closest('[data-act]') && ev.target.closest('[data-act]').getAttribute('data-act'));
      if (act === 'keep-visible') pruneToVisible();
      else if (act === 'toggle-list') { state.warnListOpen = !state.warnListOpen; renderWarn(); }
    });

    // 表格
    $('#thead').addEventListener('click', function (ev) {
      var th = ev.target.closest('th[data-sort]');
      if (!th) return;
      var k = th.getAttribute('data-sort');
      if (state.sortKey === k) state.sortDir *= -1; else { state.sortKey = k; state.sortDir = 1; }
      renderAll();
    });
    var tbody = $('#tbody');
    tbody.addEventListener('click', function (ev) {
      var clear = ev.target.closest('[data-act="clear-filters"]');
      if (clear) { clearFilters(); return; }
      var nameBtn = ev.target.closest('[data-act="detail"]');
      if (nameBtn) {
        var id = nameBtn.getAttribute('data-id');
        state.detailOpen[id] = !state.detailOpen[id];
        renderTable();
        return;
      }
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (chk) {
        var id2 = chk.getAttribute('data-id');
        if (ev.shiftKey) { shiftRange(id2, true); }
        state.anchor = id2;
        return; // change 事件负责同步选择集
      }
    });
    tbody.addEventListener('change', function (ev) {
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (!chk) return;
      var id = chk.getAttribute('data-id');
      if (chk.checked) state.selection[id] = true; else delete state.selection[id];
      state.anchor = id;
      renderAll();
    });
    $('#head-check').addEventListener('click', function () {
      var list = visibleList();
      var allSel = list.length && list.every(function (e) { return state.selection[e.id]; });
      if (allSel) list.forEach(function (e) { delete state.selection[e.id]; });
      else list.forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
    });

    // 操作条
    $('#actionbar').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-op]');
      if (!b) return;
      openPreview(b.getAttribute('data-op'));
    });
    $('#btn-ab-clear').addEventListener('click', clearSel);

    // 模态
    $('#btn-cancel').addEventListener('click', closePreview);
    $('#btn-confirm').addEventListener('click', confirmOp);
    $('#modal').addEventListener('click', function (ev) { if (ev.target === $('#modal')) closePreview(); });

    // 状态栏
    $('#statusbar').addEventListener('click', function (ev) {
      var act = ev.target.closest('[data-act]');
      if (!act) return;
      if (act.getAttribute('data-act') === 'undo') undoLast();
      if (act.getAttribute('data-act') === 'toggle-ops') { state.opsPanelOpen = !state.opsPanelOpen; renderStatusbar(); }
    });

    // 键盘契约
    document.addEventListener('keydown', function (ev) {
      if (ev.key === '/' && !/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)) {
        ev.preventDefault(); $('#search').focus();
      }
      if (ev.key === 'Escape' && state.pending) closePreview();
    });

    window.addEventListener('error', function (e) {
      var el = $('#errbanner');
      el.hidden = false;
      el.textContent = '运行错误：' + (e.message || '未知错误');
    });
  }

  function treeAct(row) {
    var id = row.getAttribute('data-id');
    var act = row.getAttribute('data-act');
    if (act === 'toggle' && (CHILDREN[id] || SEED.domains.some(function (d) { return d.id === id; }))) {
      state.expanded[id] = !state.expanded[id];
      renderAll();
    } else {
      state.scopeNodeId = id;
      renderAll();
    }
  }

  function clearFilters() {
    state.query = '';
    state.statusFilter = {};
    state.scopeNodeId = 'root';
    $('#search').value = '';
    renderAll();
  }

  // ---------- 演示场景（供自动化截图取证；不影响正常使用） ----------
  function runScene() {
    var m = /scene=(\w+)/.exec(location.search);
    if (!m) return;
    var scene = m[1];
    if (scene === 'selected') {
      // 选中「产线设备」子树全部，再筛选「在用」→ 制造隐藏已选警示 + 操作条
      entitiesInNode('c3').forEach(function (e) { state.selection[e.id] = true; });
      state.statusFilter = { active: true };
      renderAll();
    } else if (scene === 'preview') {
      entitiesInNode('c11').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('status');
      state.pending.target = 'disabled';
      renderPreviewModal();
    } else if (scene === 'delete') {
      entitiesInNode('c34').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('delete');
    }
  }

  // ---------- 启动：同步就绪，无加载态 ----------
  wire();
  renderAll();
  runScene();
})();

input.content:
/* cell-j01-s01 实体目录管理台 — 应用核心
 * 架构：单一数据源（内存实体数组）+ 派生渲染；
 * 状态归属：selection（选择集）/ query（筛选器）/ mode（预览模态）/ viewport（树展开）四类状态各有唯一属主。
 * 零误伤契约：computeAffected() 是预览与执行的唯一共同来源——确认列表与实际作用集合逐 id 一致。 */
(function () {
  'use strict';

  var SEED = window.SEED;
  var STATUSES = SEED.statuses;
  var STATUS_BY_ID = {};
  STATUSES.forEach(function (s) { STATUS_BY_ID[s.id] = s; });

  // ---------- 索引 ----------
  var CAT_BY_ID = {};
  SEED.categories.forEach(function (c) { CAT_BY_ID[c.id] = c; });
  var CHILDREN = {};
  SEED.categories.forEach(function (c) {
    if (c.parentId) { (CHILDREN[c.parentId] = CHILDREN[c.parentId] || []).push(c); }
  });
  var DOMAIN_CATS = {};
  SEED.categories.forEach(function (c) {
    if (!c.parentId) { (DOMAIN_CATS[c.domainId] = DOMAIN_CATS[c.domainId] || []).push(c); }
  });
  var ENT_BY_ID = {};
  SEED.entities.forEach(function (e) { ENT_BY_ID[e.id] = e; });

  // ---------- 状态（各有唯一属主） ----------
  var state = {
    // query —— 筛选器：只决定可见行，永不触碰 selection
    scopeNodeId: 'root',
    query: '',
    statusFilter: {},        // {statusId:true} 有勾选=只显示勾选状态
    sortKey: 'id',
    sortDir: 1,
    // selection —— 选择集：仅 行复选 / 范围全选 / 清空 / 仅保留可见 四种显式动作可变
    selection: {},           // {entityId:true}
    // viewport —— 树展开状态
    expanded: { root: true },
    // mode —— 预览确认模态（暂存待执行操作）
    pending: null,
    // 操作记录
    ops: [],
    lastOp: null,
    // 交互辅助
    anchor: null,            // shift 范围选择锚点
    detailOpen: {},          // 行内展开
    warnListOpen: false,
    opsPanelOpen: false
  };

  SEED.domains.forEach(function (d) { state.expanded[d.id] = true; });
  SEED.categories.forEach(function (c) { if (c.depth <= 1) state.expanded[c.id] = true; });

  // ---------- 纯派生 ----------
  function allEntities() { return SEED.entities; }

  function catPath(catId) {
    var parts = [], c = CAT_BY_ID[catId];
    while (c) { parts.unshift(c.name); c = c.parentId ? CAT_BY_ID[c.parentId] : null; }
    return parts;
  }
  function pathText(catId) { return catPath(catId).join(' / '); }
  function statusOf(e) { return STATUS_BY_ID[e.status]; }

  function subtreeCatIds(nodeId) {
    if (nodeId === 'root') return SEED.categories.map(function (c) { return c.id; });
    var out = [nodeId], queue = [nodeId];
    while (queue.length) {
      var cur = queue.shift();
      (CHILDREN[cur] || []).forEach(function (ch) { out.push(ch.id); queue.push(ch.id); });
    }
    return out;
  }

  function entitiesInNode(nodeId) {
    var ids = subtreeCatIds(nodeId), set = {};
    ids.forEach(function (id) { set[id] = true; });
    return allEntities().filter(function (e) { return set[e.categoryId]; });
  }

  function visibleList() {
    var q = state.query.trim().toLowerCase();
    var scopeIds = subtreeCatIds(state.scopeNodeId), scopeSet = {};
    scopeIds.forEach(function (id) { scopeSet[id] = true; });
    var list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (state.statusFilter[e.status]) return false ? false : false || true; // 占位防优化，实际判断见下
    });
    // 状态筛选：未勾选任何状态 = 全部显示；有勾选 = 只显示勾选状态
    var anyFilter = STATUSES.some(function (s) { return state.statusFilter[s.id]; });
    list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (anyFilter && !state.statusFilter[e.status]) return false;
      return true;
    });
    if (q) {
      list = list.filter(function (e) {
        return (e.id + ' ' + e.name + ' ' + e.owner + ' ' + e.tags.join(' ') + ' ' + pathText(e.categoryId))
          .toLowerCase().indexOf(q) !== -1;
      });
    }
    var k = state.sortKey, dir = state.sortDir;
    list.sort(function (a, b) {
      var va, vb;
      if (k === 'status') { va = statusOf(a).label; vb = statusOf(b).label; }
      else if (k === 'path') { va = pathText(a.categoryId); vb = pathText(b.categoryId); }
      else { va = a[k]; vb = b[k]; }
      return va < vb ? -dir : va > vb ? dir : (a.id < b.id ? -1 : 1);
    });
    return list;
  }

  // 节点聚合：直接计数 / 累计计数 / 状态分布（树、表格、状态栏三处同源）
  function nodeAgg(nodeId) {
    var direct = nodeId === 'root' ? 0
      : allEntities().filter(function (e) { return e.categoryId === nodeId; }).length;
    var list = entitiesInNode(nodeId);
    var dist = {};
    STATUSES.forEach(function (s) { dist[s.id] = 0; });
    list.forEach(function (e) { dist[e.status] += 1; });
    return { total: list.length, direct: direct, dist: dist };
  }

  function selectedIds() {
    return Object.keys(state.selection);
  }
  function hiddenSelected() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    return selectedIds().filter(function (id) { return !vis[id]; });
  }

  // ---------- 零误伤核心：预览与执行共用同一计算 ----------
  // 返回 {apply:[{id,name,path,before,after,...}], noop:[{id,name,path,reason}]}
  function computeAffected(ids, op) {
    var apply = [], noop = [];
    ids.forEach(function (id) {
      var e = ENT_BY_ID[id];
      var item = { id: id, name: e.name, path: pathText(e.categoryId), e: e };
      if (op.type === 'status') {
        if (e.status === op.target) { item.reason = '已是「' + statusOf(e).label + '」'; noop.push(item); return; }
        item.before = e.status; item.after = op.target;
      } else if (op.type === 'move') {
        if (e.categoryId === op.target) { item.reason = '已在该类别'; noop.push(item); return; }
        item.beforePath = pathText(e.categoryId); item.afterPath = pathText(op.target);
      } else if (op.type === 'tag-add') {
        var add = op.tags.filter(function (t) { return e.tags.indexOf(t) === -1; });
        if (!add.length) { item.reason = '已含全部目标标签'; noop.push(item); return; }
        item.beforeTags = e.tags.slice(); item.afterTags = e.tags.concat(add);
      } else if (op.type === 'tag-remove') {
        if (e.tags.indexOf(op.tag) === -1) { item.reason = '不含标签「' + op.tag + '」'; noop.push(item); return; }
        item.beforeTags = e.tags.slice();
        item.afterTags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        item.before = e.status;
      }
      apply.push(item);
    });
    return { apply: apply, noop: noop };
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // ---------- 渲染 ----------
  function statusBadge(sid) {
    var s = STATUS_BY_ID[sid];
    return '<span class="badge tone-' + s.tone + '">' + s.label + '</span>';
  }

  function countsHtml(agg) {
    // 显示「直接 · 累计」；叶节点直接=累计时只显示一个数
    if (agg.direct && agg.direct !== agg.total) {
      return '<span class="tcount" title="直接 ' + agg.direct + ' · 累计 ' + agg.total + '">' +
        '<b>' + agg.direct + '</b>·' + agg.total + '</span>';
    }
    return '<span class="tcount" title="累计 ' + agg.total + '">' + agg.total + '</span>';
  }

  function microBar(agg) {
    if (!agg.total) return '<span class="mbar" title="无实体"></span>';
    var segs = STATUSES.map(function (s) {
      var n = agg.dist[s.id];
      return n ? '<i class="tone-' + s.tone + '" style="flex:' + n + '" title="' + s.label + ' ' + n + '"></i>' : '';
    }).join('');
    return '<span class="mbar">' + segs + '</span>';
  }

  function trowHtml(id, name, openable, open, scoped, countAgg) {
    return '<div class="trow' + (scoped ? ' scoped' : '') + '" role="treeitem" tabindex="0"' +
      (openable ? ' aria-expanded="' + !!open + '"' : '') +
      ' data-act="scope" data-id="' + id + '">' +
      (openable ? '<span class="caret' + (open ? ' open' : '') + '" data-act="caret" data-id="' + id + '" title="展开/收起">▸</span>'
                : '<span class="caret leaf"></span>') +
      '<span class="tname">' + esc(name) + '</span>' + countsHtml(countAgg) + microBar(countAgg) + '</div>';
  }

  function renderTree() {
    var rootAgg = nodeAgg('root');
    var html = '<div class="tnode depth-0' + (state.scopeNodeId === 'root' ? ' scoped' : '') + '">' +
      trowHtml('root', '全部实体', false, false, state.scopeNodeId === 'root', rootAgg) + '</div>';
    SEED.domains.forEach(function (d) {
      var agg = nodeAgg(d.id);
      var open = !!state.expanded[d.id];
      var kids = (DOMAIN_CATS[d.id] || []).map(function (c) { return catNode(c, 1); }).join('');
      html += '<div class="tnode depth-0">' +
        trowHtml(d.id, d.name, true, open, state.scopeNodeId === d.id, agg) +
        (open ? '<div class="tkids">' + kids + '</div>' : '') + '</div>';
    });
    document.getElementById('tree').innerHTML = html;
  }

  function catNode(c, depth) {
    var agg = nodeAgg(c.id);
    var kids = CHILDREN[c.id] || [];
    var open = !!state.expanded[c.id];
    var childHtml = kids.length && open ? '<div class="tkids">' + kids.map(function (ch) { return catNode(ch, depth + 1); }).join('') + '</div>' : '';
    return '<div class="tnode depth-' + depth + '">' +
      trowHtml(c.id, c.name, kids.length > 0, open, state.scopeNodeId === c.id, agg) +
      childHtml + '</div>';
  }

  function renderToolbar() {
    var scopeName = state.scopeNodeId === 'root' ? '全部实体' : pathText(state.scopeNodeId);
    document.getElementById('scope-crumb').textContent = '范围：' + scopeName + '（含子层级）';
    var vis = visibleList().length;
    var sub = entitiesInNode(state.scopeNodeId).length;
    document.getElementById('btn-sel-visible').textContent = '选当前筛选结果 (' + vis + ')';
    document.getElementById('btn-sel-subtree').textContent = '选子树全部 (' + sub + ')';
    // 状态 chips（全局计数，点击=只显示该状态）
    var distAll = {};
    STATUSES.forEach(function (s) { distAll[s.id] = 0; });
    allEntities().forEach(function (e) { distAll[e.status] += 1; });
    document.getElementById('status-chips').innerHTML = STATUSES.map(function (s) {
      var on = !!state.statusFilter[s.id];
      return '<button class="chip tone-' + s.tone + (on ? ' on' : '') + '" data-act="status-chip" data-id="' + s.id + '"' +
        ' aria-pressed="' + on + '" title="' + (on ? '取消「只显示' : '只显示') + s.label + (on ? '」' : '」') + '">' +
        s.label + ' <b>' + distAll[s.id] + '</b></button>';
    }).join('');
  }

  function renderWarn() {
    var hidden = hiddenSelected();
    var el = document.getElementById('warn');
    var listEl = document.getElementById('warn-list');
    if (!hidden.length) {
      el.hidden = true; listEl.hidden = true; state.warnListOpen = false;
      return;
    }
    el.hidden = false;
    document.getElementById('warn-text').textContent =
      '已选 ' + selectedIds().length + ' 项中有 ' + hidden.length +
      ' 项被当前筛选/范围隐藏——批量操作仍会包含它们。';
    listEl.hidden = !state.warnListOpen;
    if (state.warnListOpen) {
      listEl.innerHTML = hidden.map(function (id) {
        var e = ENT_BY_ID[id];
        return '<div class="warn-item"><code>' + esc(id) + '</code> ' + esc(e.name) +
          ' <span class="dim">· ' + esc(pathText(e.categoryId)) + '</span></div>';
      }).join('');
    }
  }

  function renderTable() {
    var list = visibleList();
    var tbody = document.getElementById('tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr class="empty-row"><td colspan="8"><div class="empty">' +
        '<div class="empty-title">当前范围内没有匹配的实体</div>' +
        '<div class="dim">调整关键字或状态筛选，或<span class="link" data-act="clear-filters" tabindex="0">清除全部筛选</span></div>' +
        '</div></td></tr>';
    } else {
      tbody.innerHTML = list.map(function (e) {
        var sel = !!state.selection[e.id];
        var open = !!state.detailOpen[e.id];
        var row = '<tr class="ent' + (sel ? ' sel' : '') + '" data-id="' + e.id + '">' +
          '<td class="c-check"><input type="checkbox" data-act="row-check" data-id="' + e.id + '"' +
          (sel ? ' checked' : '') + ' aria-label="选择 ' + esc(e.name) + '"></td>' +
          '<td class="c-code"><code>' + esc(e.id) + '</code></td>' +
          '<td class="c-name"><button class="name-btn" data-act="detail" data-id="' + e.id + '" aria-expanded="' + open + '">' +
          '<span class="chev">' + (open ? '▾' : '▸') + '</span>' + esc(e.name) + '</button></td>' +
          '<td class="c-status">' + statusBadge(e.status) + '</td>' +
          '<td class="c-path">' + esc(pathText(e.categoryId)) + '</td>' +
          '<td class="c-owner">' + esc(e.owner) + '</td>' +
          '<td class="c-tags">' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join('') : '<span class="dim">—</span>') + '</td>' +
          '<td class="c-date">' + esc(e.updatedAt) + '</td></tr>';
        if (open) {
          row += '<tr class="detail"><td></td><td colspan="7"><div class="detail-card">' +
            '<div><b>编码</b><code>' + esc(e.id) + '</code></div>' +
            '<div><b>归属</b>' + esc(pathText(e.categoryId)) + '</div>' +
            '<div><b>状态</b>' + statusBadge(e.status) + '</div>' +
            '<div><b>负责人</b>' + esc(e.owner) + '</div>' +
            '<div><b>标签</b>' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join(' ') : '—') + '</div>' +
            '<div><b>备注</b>' + esc(e.note) + '</div>' +
            '<div><b>更新</b>' + esc(e.updatedAt) + '</div></div></td></tr>';
        }
        return row;
      }).join('');
    }
    // 表头三态复选框
    var visIds = list.map(function (e) { return e.id; });
    var selVis = visIds.filter(function (id) { return state.selection[id]; }).length;
    var head = document.getElementById('head-check');
    head.checked = visIds.length > 0 && selVis === visIds.length;
    head.indeterminate = selVis > 0 && selVis < visIds.length;
    document.getElementById('sel-summary').textContent =
      '已选 ' + selectedIds().length + ' · 可见 ' + visIds.length + ' · 范围内 ' + entitiesInNode(state.scopeNodeId).length;
    // 排序指示
    Array.prototype.forEach.call(document.querySelectorAll('#thead th[data-sort]'), function (th) {
      var on = th.getAttribute('data-sort') === state.sortKey;
      th.setAttribute('aria-sort', on ? (state.sortDir === 1 ? 'ascending' : 'descending') : 'none');
      th.querySelector('.sort-ind').textContent = on ? (state.sortDir === 1 ? '▲' : '▼') : '';
    });
  }

  function renderActionbar() {
    var n = selectedIds().length;
    var bar = document.getElementById('actionbar');
    bar.hidden = n === 0;
    if (!n) return;
    var hidden = hiddenSelected().length;
    document.getElementById('ab-count').innerHTML = '已选 <b>' + n + '</b> 项' +
      (hidden ? ' <span class="ab-hidden">（' + hidden + ' 项当前不可见，仍将包含）</span>' : '');
  }

  function renderStatusbar() {
    var el = document.getElementById('receipt');
    if (state.lastOp && !state.lastOp.undone) {
      el.innerHTML = '<span class="rc-ok">✓</span> ' + esc(state.lastOp.receipt) +
        ' <button class="btn btn-mini" data-act="undo">撤销</button>';
    } else if (state.lastOp && state.lastOp.undone) {
      el.innerHTML = '<span class="dim">已撤销：' + esc(state.lastOp.receipt) + '</span>';
    } else {
      el.innerHTML = '<span class="dim">就绪 · 批量操作经逐项预览确认后生效</span>';
    }
    document.getElementById('ops-btn').textContent = '操作记录 (' + state.ops.length + ')';
    var panel = document.getElementById('ops-panel');
    panel.hidden = !state.opsPanelOpen;
    if (state.opsPanelOpen) {
      panel.innerHTML = state.ops.length
        ? state.ops.slice().reverse().map(function (op) {
          return '<div class="op-item' + (op.undone ? ' undone' : '') + '">' +
            '<span class="op-time">' + esc(op.time) + '</span> ' + esc(op.label) +
            (op.undone ? ' <span class="op-undone">已撤销</span>' : '') + '</div>';
        }).join('')
        : '<div class="dim op-item">暂无操作</div>';
    }
  }

  function renderAll() {
    renderTree();
    renderToolbar();
    renderWarn();
    renderTable();
    renderActionbar();
    renderStatusbar();
  }

  // ---------- 选择集动作（唯一合法入口） ----------
  function addVisible() {
    visibleList().forEach(function (e) { state.selection[e.id] = true; });
    renderAll();
  }
  function addSubtree() {
    entitiesInNode(state.scopeNodeId).forEach(function (e) { state.selection[e.id] = true; });
    renderAll();
  }
  function clearSel() { state.selection = {}; state.anchor = null; renderAll(); }
  function pruneToVisible() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    selectedIds().forEach(function (id) { if (!vis[id]) delete state.selection[id]; });
    renderAll();
  }
  function shiftRange(currentId) {
    var visIds = visibleList().map(function (e) { return e.id; });
    var a = visIds.indexOf(state.anchor), b = visIds.indexOf(currentId);
    if (a === -1 || b === -1) { state.anchor = currentId; return; }
    if (a > b) { var t = a; a = b; b = t; }
    for (var i = a; i <= b; i++) state.selection[visIds[i]] = true;
    renderAll();
  }

  // ---------- 批量操作引擎 ----------
  var OP_META = {
    'status':     { title: '批量修改状态' },
    'move':       { title: '批量移动类别' },
    'tag-add':    { title: '批量添加标签' },
    'tag-remove': { title: '批量移除标签' },
    'delete':     { title: '批量删除实体' }
  };

  function openPreview(type) {
    var ids = selectedIds();
    if (!ids.length) return;
    state.pending = { type: type, ids: ids, target: '', tags: '', confirmDelete: false };
    renderPreviewModal();
    document.getElementById('modal').hidden = false;
    var first = document.querySelector('#modal-ctrl select, #modal-ctrl input[type=text]');
    if (first) first.focus();
  }

  function closePreview() {
    state.pending = null;
    document.getElementById('modal').hidden = true;
  }

  function renderPreviewModal() {
    var p = state.pending;
    if (!p) return;
    document.getElementById('modal-title').textContent = OP_META[p.type].title;

    // 控制区
    var ctrl = document.getElementById('modal-ctrl');
    if (p.type === 'status') {
      ctrl.innerHTML = '<label>目标状态</label><select id="op-target" aria-label="目标状态">' +
        '<option value="">— 选择目标状态 —</option>' +
        STATUSES.map(function (s) {
          return '<option value="' + s.id + '"' + (p.target === s.id ? ' selected' : '') + '>' + s.label + '</option>';
        }).join('') + '</select>';
    } else if (p.type === 'move') {
      var opts = SEED.categories.map(function (c) {
        return '<option value="' + c.id + '"' + (p.target === c.id ? ' selected' : '') + '>' +
          '　'.repeat(c.depth) + esc(c.name) + '（' + esc(CAT_BY_ID[c.domainId].name) + '）</option>';
      }).join('');
      ctrl.innerHTML = '<label>目标类别</label><select id="op-target" aria-label="目标类别">' +
        '<option value="">— 选择目标类别 —</option>' + opts + '</select>';
    } else if (p.type === 'tag-add') {
      ctrl.innerHTML = '<label>新标签（逗号分隔）</label><input type="text" id="op-tags" placeholder="如：待巡检, 核心">';
    } else if (p.type === 'tag-remove') {
      var tagSet = {};
      p.ids.forEach(function (id) { ENT_BY_ID[id].tags.forEach(function (t) { tagSet[t] = true; }); });
      var tagOpts = Object.keys(tagSet).map(function (t) {
        return '<option value="' + esc(t) + '"' + (p.target === t ? ' selected' : '') + '>' + esc(t) + '</option>';
      }).join('');
      ctrl.innerHTML = '<label>要移除的标签</label><select id="op-target" aria-label="要移除的标签">' +
        '<option value="">— 选择标签 —</option>' + tagOpts + '</select>';
    } else {
      ctrl.innerHTML = '<label class="danger-label"><input type="checkbox" id="op-confirm-del"> ' +
        '我确认删除以下 <b>' + p.ids.length + '</b> 项（操作后可撤销）</label>';
    }

    // 控件事件
    var targetSel = document.getElementById('op-target');
    if (targetSel) targetSel.addEventListener('change', function () {
      state.pending.target = this.value;
      renderPreviewModal();
      var s = document.getElementById('op-target');
      if (s) s.focus();
    });
    var tagsInput = document.getElementById('op-tags');
    if (tagsInput) {
      tagsInput.value = p.tags;
      tagsInput.addEventListener('input', function () {
        state.pending.tags = this.value;
        renderPreviewModal();
        var i2 = document.getElementById('op-tags');
        i2.focus();
        i2.setSelectionRange(i2.value.length, i2.value.length);
      });
    }
    var delChk = document.getElementById('op-confirm-del');
    if (delChk) delChk.addEventListener('change', function () {
      state.pending.confirmDelete = this.checked;
      renderPreviewModal();
    });

    // 受影响集合（预览 = 执行的唯一来源）
    var op = pendingOp();
    var aff = op
      ? computeAffected(p.ids, op)
      : { apply: [], noop: p.ids.map(function (id) {
          var e = ENT_BY_ID[id];
          return { id: id, name: e.name, path: pathText(e.categoryId), reason: '尚未选择目标' };
        }) };

    document.getElementById('modal-summary').innerHTML =
      '<span class="mchip">已选 <b>' + p.ids.length + '</b> 项</span>' +
      '<span class="mchip ok">将生效 <b>' + aff.apply.length + '</b> 项</span>' +
      (aff.noop.length ? '<span class="mchip dim2">跳过（无变更）<b>' + aff.noop.length + '</b> 项</span>' : '');

    var rows = aff.apply.map(function (it) {
      var detail = '';
      if (p.type === 'status') detail = statusBadge(it.before) + ' <span class="arrow">→</span> ' + statusBadge(it.after);
      else if (p.type === 'move') detail = '<span class="dim small">' + esc(it.beforePath) + '</span> <span class="arrow">→</span> <span class="small">' + esc(it.afterPath) + '</span>';
      else if (p.type === 'tag-add' || p.type === 'tag-remove') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else detail = statusBadge(it.before) + ' <span class="arrow">→</span> <span class="badge tone-danger">删除</span>';
      return '<div class="aff-row"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change">' + detail + '</span></div>';
    }).join('');
    var noopRows = aff.noop.map(function (it) {
      return '<div class="aff-row noop"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change dim">' + esc(it.reason) + '</span></div>';
    }).join('');
    document.getElementById('modal-list').innerHTML =
      (rows ? '<div class="aff-head">将生效（' + aff.apply.length + '）</div>' + rows : '') +
      (noopRows ? '<div class="aff-head dim-head">跳过——无变更（' + aff.noop.length + '）</div>' + noopRows : '');

    // 错误/可用性
    var err = validatePending();
    document.getElementById('modal-error').textContent = err || '';
    var btn = document.getElementById('btn-confirm');
    btn.disabled = !!err;
    btn.textContent = p.type === 'delete'
      ? '确认删除 ' + aff.apply.length + ' 项'
      : '确认执行（' + aff.apply.length + ' 项）';
  }

  function tagsText(tags, highlight) {
    if (!tags || !tags.length) return '<span class="dim">—</span>';
    return tags.map(function (t) {
      return '<span class="tag' + (highlight ? ' hl' : '') + '">' + esc(t) + '</span>';
    }).join(' ');
  }

  function pendingOp() {
    var p = state.pending;
    if (!p) return null;
    if (p.type === 'status' && p.target) return { type: 'status', target: p.target };
    if (p.type === 'move' && p.target) return { type: 'move', target: p.target };
    if (p.type === 'tag-add') {
      var tags = p.tags.split(/[,，]/).map(function (t) { return t.trim(); }).filter(Boolean);
      return tags.length ? { type: 'tag-add', tags: tags } : null;
    }
    if (p.type === 'tag-remove' && p.target) return { type: 'tag-remove', tag: p.target };
    if (p.type === 'delete') return { type: 'delete' };
    return null;
  }

  function validatePending() {
    var p = state.pending;
    if (!p) return '内部错误';
    var op = pendingOp();
    if (!op) {
      if (p.type === 'delete') return '请先勾选确认框';
      return p.type === 'tag-add' ? '请输入至少一个标签' : '请选择目标';
    }
    var aff = computeAffected(p.ids, op);
    if (!aff.apply.length) return '没有可生效的变更（全部所选实体已处于目标状态/位置）';
    if (p.type === 'delete' && !p.confirmDelete) return '请先勾选确认框';
    return '';
  }

  function confirmOp() {
    var p = state.pending;
    if (!p || validatePending()) return;
    var op = pendingOp();
    var aff = computeAffected(p.ids, op); // 与预览同一函数：作用集合=确认集合
    var time = new Date().toTimeString().slice(0, 8);
    // 快照含全字段，删除也可精确恢复
    var snapshot = aff.apply.map(function (it) {
      var e = it.e;
      return {
        id: e.id, name: e.name, owner: e.owner, note: e.note, updatedAt: e.updatedAt,
        status: e.status, categoryId: e.categoryId, tags: e.tags.slice()
      };
    });
    aff.apply.forEach(function (it) {
      var e = it.e;
      if (op.type === 'status') e.status = op.target;
      else if (op.type === 'move') e.categoryId = op.target;
      else if (op.type === 'tag-add') {
        op.tags.forEach(function (t) { if (e.tags.indexOf(t) === -1) e.tags.push(t); });
      } else if (op.type === 'tag-remove') {
        e.tags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        e._deleted = true;
      }
    });
    if (op.type === 'delete') {
      SEED.entities = SEED.entities.filter(function (e) { return !e._deleted; });
      aff.apply.forEach(function (it) {
        delete ENT_BY_ID[it.id];
        delete state.selection[it.id];
        delete state.detailOpen[it.id];
      });
    }
    var receipt;
    if (op.type === 'status') receipt = '已将 ' + aff.apply.length + ' 项状态改为「' + STATUS_BY_ID[op.target].label + '」';
    else if (op.type === 'move') receipt = '已将 ' + aff.apply.length + ' 项移动到「' + pathText(op.target) + '」';
    else if (op.type === 'tag-add') receipt = '已为 ' + aff.apply.length + ' 项添加标签「' + op.tags.join('、') + '」';
    else if (op.type === 'tag-remove') receipt = '已从 ' + aff.apply.length + ' 项移除标签「' + op.tag + '」';
    else receipt = '已删除 ' + aff.apply.length + ' 项';
    var record = {
      time: time,
      label: OP_META[p.type].title + ' ' + p.ids.length + ' 项',
      receipt: receipt,
      snapshot: snapshot,
      type: op.type,
      undone: false
    };
    state.ops.push(record);
    state.lastOp = record;
    state.pending = null;
    state.selection = {};
    state.anchor = null;
    document.getElementById('modal').hidden = true;
    renderAll();
  }

  function undoLast() {
    var op = state.lastOp;
    if (!op || op.undone) return;
    if (op.type === 'delete') {
      op.snapshot.forEach(function (s) {
        var e = {
          id: s.id, name: s.name, owner: s.owner, note: s.note, updatedAt: s.updatedAt,
          status: s.status, categoryId: s.categoryId, tags: s.tags.slice()
        };
        SEED.entities.push(e);
        ENT_BY_ID[s.id] = e;
      });
    } else {
      op.snapshot.forEach(function (s) {
        var e = ENT_BY_ID[s.id];
        if (!e) return;
        e.status = s.status;
        e.categoryId = s.categoryId;
        e.tags = s.tags.slice();
      });
    }
    op.undone = true;
    state.lastOp = null;
    renderAll();
  }

  // ---------- 事件 ----------
  function treeToggle(id) { state.expanded[id] = !state.expanded[id]; renderAll(); }

  function wire() {
    var tree = document.getElementById('tree');
    tree.addEventListener('click', function (ev) {
      var caret = ev.target.closest('.caret[data-act="caret"]');
      if (caret) { treeToggle(caret.getAttribute('data-id')); return; }
      var row = ev.target.closest('.trow');
      if (!row) return;
      state.scopeNodeId = row.getAttribute('data-id');
      renderAll();
    });
    tree.addEventListener('keydown', function (ev) {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      var row = ev.target.closest('.trow');
      if (!row) return;
      ev.preventDefault();
      state.scopeNodeId = row.getAttribute('data-id');
      renderAll();
    });

    // 工具栏
    document.getElementById('search').addEventListener('input', function () {
      state.query = this.value;
      renderAll();
    });
    document.getElementById('status-chips').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act="status-chip"]');
      if (!b) return;
      var id = b.getAttribute('data-id');
      if (state.statusFilter[id]) delete state.statusFilter[id];
      else state.statusFilter[id] = true;
      renderAll();
    });
    document.getElementById('btn-sel-visible').addEventListener('click', addVisible);
    document.getElementById('btn-sel-subtree').addEventListener('click', addSubtree);
    document.getElementById('btn-clear-filters').addEventListener('click', clearFilters);

    // 警示条
    document.getElementById('warn-strip').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act]');
      if (!b) return;
      var act = b.getAttribute('data-act');
      if (act === 'keep-visible') pruneToVisible();
      else if (act === 'toggle-list') { state.warnListOpen = !state.warnListOpen; renderWarn(); }
    });

    // 表格
    document.getElementById('thead').addEventListener('click', function (ev) {
      var th = ev.target.closest('th[data-sort]');
      if (!th) return;
      var k = th.getAttribute('data-sort');
      if (state.sortKey === k) state.sortDir *= -1;
      else { state.sortKey = k; state.sortDir = 1; }
      renderAll();
    });
    var tbody = document.getElementById('tbody');
    tbody.addEventListener('click', function (ev) {
      if (ev.target.closest('[data-act="clear-filters"]')) { clearFilters(); return; }
      var nameBtn = ev.target.closest('[data-act="detail"]');
      if (nameBtn) {
        var idd = nameBtn.getAttribute('data-id');
        state.detailOpen[idd] = !state.detailOpen[idd];
        renderTable();
        return;
      }
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (chk && ev.shiftKey && state.anchor) {
        ev.preventDefault(); // 范围选择=只加选，不翻转当前框
        shiftRange(chk.getAttribute('data-id'));
      }
    });
    tbody.addEventListener('change', function (ev) {
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (!chk) return;
      var id = chk.getAttribute('data-id');
      if (chk.checked) state.selection[id] = true;
      else delete state.selection[id];
      state.anchor = id;
      renderAll();
    });
    document.getElementById('head-check').addEventListener('click', function () {
      var list = visibleList();
      var allSel = list.length && list.every(function (e) { return state.selection[e.id]; });
      if (allSel) list.forEach(function (e) { delete state.selection[e.id]; });
      else list.forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
    });

    // 操作条
    document.getElementById('actionbar').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-op]');
      if (!b) return;
      openPreview(b.getAttribute('data-op'));
    });
    document.getElementById('btn-ab-clear').addEventListener('click', clearSel);

    // 模态
    document.getElementById('btn-cancel').addEventListener('click', closePreview);
    document.getElementById('btn-confirm').addEventListener('click', confirmOp);
    document.getElementById('modal').addEventListener('click', function (ev) {
      if (ev.target === document.getElementById('modal')) closePreview();
    });

    // 状态栏
    document.getElementById('statusbar').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act]');
      if (!b) return;
      var act = b.getAttribute('data-act');
      if (act === 'undo') undoLast();
      else if (act === 'toggle-ops') { state.opsPanelOpen = !state.opsPanelOpen; renderStatusbar(); }
    });

    // 键盘契约：/ 聚焦搜索；Esc 关闭模态
    document.addEventListener('keydown', function (ev) {
      var tag = document.activeElement ? document.activeElement.tagName : '';
      if (ev.key === '/' && !/INPUT|SELECT|TEXTAREA/.test(tag)) {
        ev.preventDefault();
        document.getElementById('search').focus();
      }
      if (ev.key === 'Escape' && state.pending) closePreview();
    });

    window.addEventListener('error', function (e) {
      var el = document.getElementById('errbanner');
      el.hidden = false;
      el.textContent = '运行错误：' + (e.message || '未知错误');
    });
  }

  function clearFilters() {
    state.query = '';
    state.statusFilter = {};
    state.scopeNodeId = 'root';
    document.getElementById('search').value = '';
    renderAll();
  }

  // ---------- 演示场景（供自动化截图取证；不影响正常使用） ----------
  function runScene() {
    var m = /scene=(\w+)/.exec(location.search);
    if (!m) return;
    var scene = m[1];
    if (scene === 'selected') {
      // 选中「产线设备」子树全部，再只显示「在用」→ 隐藏已选警示 + 操作条
      entitiesInNode('c3').forEach(function (e) { state.selection[e.id] = true; });
      state.statusFilter = { active: true };
      renderAll();
    } else if (scene === 'preview') {
      entitiesInNode('c11').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('status');
      state.pending.target = 'disabled';
      renderPreviewModal();
    } else if (scene === 'delete') {
      entitiesInNode('c34').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('delete');
    } else if (scene === 'detail') {
      var first = visibleList()[0];
      if (first) state.detailOpen[first.id] = true;
      entitiesInNode('c21').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
    }
  }

  // ---------- 启动：同步就绪，无加载态 ----------
  wire();
  renderAll();
  runScene();
})();

tool_use_result.content:
/* cell-j01-s01 实体目录管理台 — 应用核心
 * 架构：单一数据源（内存实体数组）+ 派生渲染；
 * 状态归属：selection（选择集）/ query（筛选器）/ mode（预览模态）/ viewport（树展开）四类状态各有唯一属主。
 * 零误伤契约：computeAffected() 是预览与执行的唯一共同来源——确认列表与实际作用集合逐 id 一致。 */
(function () {
  'use strict';

  var SEED = window.SEED;
  var STATUSES = SEED.statuses;
  var STATUS_BY_ID = {};
  STATUSES.forEach(function (s) { STATUS_BY_ID[s.id] = s; });

  // ---------- 索引 ----------
  var CAT_BY_ID = {};
  SEED.categories.forEach(function (c) { CAT_BY_ID[c.id] = c; });
  var CHILDREN = {};
  SEED.categories.forEach(function (c) {
    if (c.parentId) { (CHILDREN[c.parentId] = CHILDREN[c.parentId] || []).push(c); }
  });
  var DOMAIN_CATS = {};
  SEED.categories.forEach(function (c) {
    if (!c.parentId) { (DOMAIN_CATS[c.domainId] = DOMAIN_CATS[c.domainId] || []).push(c); }
  });
  var ENT_BY_ID = {};
  SEED.entities.forEach(function (e) { ENT_BY_ID[e.id] = e; });

  // ---------- 状态（各有唯一属主） ----------
  var state = {
    // query —— 筛选器：只决定可见行，永不触碰 selection
    scopeNodeId: 'root',
    query: '',
    statusFilter: {},        // {statusId:true} 有勾选=只显示勾选状态
    sortKey: 'id',
    sortDir: 1,
    // selection —— 选择集：仅 行复选 / 范围全选 / 清空 / 仅保留可见 四种显式动作可变
    selection: {},           // {entityId:true}
    // viewport —— 树展开状态
    expanded: { root: true },
    // mode —— 预览确认模态（暂存待执行操作）
    pending: null,
    // 操作记录
    ops: [],
    lastOp: null,
    // 交互辅助
    anchor: null,            // shift 范围选择锚点
    detailOpen: {},          // 行内展开
    warnListOpen: false,
    opsPanelOpen: false
  };

  SEED.domains.forEach(function (d) { state.expanded[d.id] = true; });
  SEED.categories.forEach(function (c) { if (c.depth <= 1) state.expanded[c.id] = true; });

  // ---------- 纯派生 ----------
  function allEntities() { return SEED.entities; }

  function catPath(catId) {
    var parts = [], c = CAT_BY_ID[catId];
    while (c) { parts.unshift(c.name); c = c.parentId ? CAT_BY_ID[c.parentId] : null; }
    return parts;
  }
  function pathText(catId) { return catPath(catId).join(' / '); }
  function statusOf(e) { return STATUS_BY_ID[e.status]; }

  function subtreeCatIds(nodeId) {
    if (nodeId === 'root') return SEED.categories.map(function (c) { return c.id; });
    var out = [nodeId], queue = [nodeId];
    while (queue.length) {
      var cur = queue.shift();
      (CHILDREN[cur] || []).forEach(function (ch) { out.push(ch.id); queue.push(ch.id); });
    }
    return out;
  }

  function entitiesInNode(nodeId) {
    var ids = subtreeCatIds(nodeId), set = {};
    ids.forEach(function (id) { set[id] = true; });
    return allEntities().filter(function (e) { return set[e.categoryId]; });
  }

  function visibleList() {
    var q = state.query.trim().toLowerCase();
    var scopeIds = subtreeCatIds(state.scopeNodeId), scopeSet = {};
    scopeIds.forEach(function (id) { scopeSet[id] = true; });
    var list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (state.statusFilter[e.status]) return false ? false : false || true; // 占位防优化，实际判断见下
    });
    // 状态筛选：未勾选任何状态 = 全部显示；有勾选 = 只显示勾选状态
    var anyFilter = STATUSES.some(function (s) { return state.statusFilter[s.id]; });
    list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (anyFilter && !state.statusFilter[e.status]) return false;
      return true;
    });
    if (q) {
      list = list.filter(function (e) {
        return (e.id + ' ' + e.name + ' ' + e.owner + ' ' + e.tags.join(' ') + ' ' + pathText(e.categoryId))
          .toLowerCase().indexOf(q) !== -1;
      });
    }
    var k = state.sortKey, dir = state.sortDir;
    list.sort(function (a, b) {
      var va, vb;
      if (k === 'status') { va = statusOf(a).label; vb = statusOf(b).label; }
      else if (k === 'path') { va = pathText(a.categoryId); vb = pathText(b.categoryId); }
      else { va = a[k]; vb = b[k]; }
      return va < vb ? -dir : va > vb ? dir : (a.id < b.id ? -1 : 1);
    });
    return list;
  }

  // 节点聚合：直接计数 / 累计计数 / 状态分布（树、表格、状态栏三处同源）
  function nodeAgg(nodeId) {
    var direct = nodeId === 'root' ? 0
      : allEntities().filter(function (e) { return e.categoryId === nodeId; }).length;
    var list = entitiesInNode(nodeId);
    var dist = {};
    STATUSES.forEach(function (s) { dist[s.id] = 0; });
    list.forEach(function (e) { dist[e.status] += 1; });
    return { total: list.length, direct: direct, dist: dist };
  }

  function selectedIds() {
    return Object.keys(state.selection);
  }
  function hiddenSelected() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    return selectedIds().filter(function (id) { return !vis[id]; });
  }

  // ---------- 零误伤核心：预览与执行共用同一计算 ----------
  // 返回 {apply:[{id,name,path,before,after,...}], noop:[{id,name,path,reason}]}
  function computeAffected(ids, op) {
    var apply = [], noop = [];
    ids.forEach(function (id) {
      var e = ENT_BY_ID[id];
      var item = { id: id, name: e.name, path: pathText(e.categoryId), e: e };
      if (op.type === 'status') {
        if (e.status === op.target) { item.reason = '已是「' + statusOf(e).label + '」'; noop.push(item); return; }
        item.before = e.status; item.after = op.target;
      } else if (op.type === 'move') {
        if (e.categoryId === op.target) { item.reason = '已在该类别'; noop.push(item); return; }
        item.beforePath = pathText(e.categoryId); item.afterPath = pathText(op.target);
      } else if (op.type === 'tag-add') {
        var add = op.tags.filter(function (t) { return e.tags.indexOf(t) === -1; });
        if (!add.length) { item.reason = '已含全部目标标签'; noop.push(item); return; }
        item.beforeTags = e.tags.slice(); item.afterTags = e.tags.concat(add);
      } else if (op.type === 'tag-remove') {
        if (e.tags.indexOf(op.tag) === -1) { item.reason = '不含标签「' + op.tag + '」'; noop.push(item); return; }
        item.beforeTags = e.tags.slice();
        item.afterTags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        item.before = e.status;
      }
      apply.push(item);
    });
    return { apply: apply, noop: noop };
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // ---------- 渲染 ----------
  function statusBadge(sid) {
    var s = STATUS_BY_ID[sid];
    return '<span class="badge tone-' + s.tone + '">' + s.label + '</span>';
  }

  function countsHtml(agg) {
    // 显示「直接 · 累计」；叶节点直接=累计时只显示一个数
    if (agg.direct && agg.direct !== agg.total) {
      return '<span class="tcount" title="直接 ' + agg.direct + ' · 累计 ' + agg.total + '">' +
        '<b>' + agg.direct + '</b>·' + agg.total + '</span>';
    }
    return '<span class="tcount" title="累计 ' + agg.total + '">' + agg.total + '</span>';
  }

  function microBar(agg) {
    if (!agg.total) return '<span class="mbar" title="无实体"></span>';
    var segs = STATUSES.map(function (s) {
      var n = agg.dist[s.id];
      return n ? '<i class="tone-' + s.tone + '" style="flex:' + n + '" title="' + s.label + ' ' + n + '"></i>' : '';
    }).join('');
    return '<span class="mbar">' + segs + '</span>';
  }

  function trowHtml(id, name, openable, open, scoped, countAgg) {
    return '<div class="trow' + (scoped ? ' scoped' : '') + '" role="treeitem" tabindex="0"' +
      (openable ? ' aria-expanded="' + !!open + '"' : '') +
      ' data-act="scope" data-id="' + id + '">' +
      (openable ? '<span class="caret' + (open ? ' open' : '') + '" data-act="caret" data-id="' + id + '" title="展开/收起">▸</span>'
                : '<span class="caret leaf"></span>') +
      '<span class="tname">' + esc(name) + '</span>' + countsHtml(countAgg) + microBar(countAgg) + '</div>';
  }

  function renderTree() {
    var rootAgg = nodeAgg('root');
    var html = '<div class="tnode depth-0' + (state.scopeNodeId === 'root' ? ' scoped' : '') + '">' +
      trowHtml('root', '全部实体', false, false, state.scopeNodeId === 'root', rootAgg) + '</div>';
    SEED.domains.forEach(function (d) {
      var agg = nodeAgg(d.id);
      var open = !!state.expanded[d.id];
      var kids = (DOMAIN_CATS[d.id] || []).map(function (c) { return catNode(c, 1); }).join('');
      html += '<div class="tnode depth-0">' +
        trowHtml(d.id, d.name, true, open, state.scopeNodeId === d.id, agg) +
        (open ? '<div class="tkids">' + kids + '</div>' : '') + '</div>';
    });
    document.getElementById('tree').innerHTML = html;
  }

  function catNode(c, depth) {
    var agg = nodeAgg(c.id);
    var kids = CHILDREN[c.id] || [];
    var open = !!state.expanded[c.id];
    var childHtml = kids.length && open ? '<div class="tkids">' + kids.map(function (ch) { return catNode(ch, depth + 1); }).join('') + '</div>' : '';
    return '<div class="tnode depth-' + depth + '">' +
      trowHtml(c.id, c.name, kids.length > 0, open, state.scopeNodeId === c.id, agg) +
      childHtml + '</div>';
  }

  function renderToolbar() {
    var scopeName = state.scopeNodeId === 'root' ? '全部实体' : pathText(state.scopeNodeId);
    document.getElementById('scope-crumb').textContent = '范围：' + scopeName + '（含子层级）';
    var vis = visibleList().length;
    var sub = entitiesInNode(state.scopeNodeId).length;
    document.getElementById('btn-sel-visible').textContent = '选当前筛选结果 (' + vis + ')';
    document.getElementById('btn-sel-subtree').textContent = '选子树全部 (' + sub + ')';
    // 状态 chips（全局计数，点击=只显示该状态）
    var distAll = {};
    STATUSES.forEach(function (s) { distAll[s.id] = 0; });
    allEntities().forEach(function (e) { distAll[e.status] += 1; });
    document.getElementById('status-chips').innerHTML = STATUSES.map(function (s) {
      var on = !!state.statusFilter[s.id];
      return '<button class="chip tone-' + s.tone + (on ? ' on' : '') + '" data-act="status-chip" data-id="' + s.id + '"' +
        ' aria-pressed="' + on + '" title="' + (on ? '取消「只显示' : '只显示') + s.label + (on ? '」' : '」') + '">' +
        s.label + ' <b>' + distAll[s.id] + '</b></button>';
    }).join('');
  }

  function renderWarn() {
    var hidden = hiddenSelected();
    var el = document.getElementById('warn');
    var listEl = document.getElementById('warn-list');
    if (!hidden.length) {
      el.hidden = true; listEl.hidden = true; state.warnListOpen = false;
      return;
    }
    el.hidden = false;
    document.getElementById('warn-text').textContent =
      '已选 ' + selectedIds().length + ' 项中有 ' + hidden.length +
      ' 项被当前筛选/范围隐藏——批量操作仍会包含它们。';
    listEl.hidden = !state.warnListOpen;
    if (state.warnListOpen) {
      listEl.innerHTML = hidden.map(function (id) {
        var e = ENT_BY_ID[id];
        return '<div class="warn-item"><code>' + esc(id) + '</code> ' + esc(e.name) +
          ' <span class="dim">· ' + esc(pathText(e.categoryId)) + '</span></div>';
      }).join('');
    }
  }

  function renderTable() {
    var list = visibleList();
    var tbody = document.getElementById('tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr class="empty-row"><td colspan="8"><div class="empty">' +
        '<div class="empty-title">当前范围内没有匹配的实体</div>' +
        '<div class="dim">调整关键字或状态筛选，或<span class="link" data-act="clear-filters" tabindex="0">清除全部筛选</span></div>' +
        '</div></td></tr>';
    } else {
      tbody.innerHTML = list.map(function (e) {
        var sel = !!state.selection[e.id];
        var open = !!state.detailOpen[e.id];
        var row = '<tr class="ent' + (sel ? ' sel' : '') + '" data-id="' + e.id + '">' +
          '<td class="c-check"><input type="checkbox" data-act="row-check" data-id="' + e.id + '"' +
          (sel ? ' checked' : '') + ' aria-label="选择 ' + esc(e.name) + '"></td>' +
          '<td class="c-code"><code>' + esc(e.id) + '</code></td>' +
          '<td class="c-name"><button class="name-btn" data-act="detail" data-id="' + e.id + '" aria-expanded="' + open + '">' +
          '<span class="chev">' + (open ? '▾' : '▸') + '</span>' + esc(e.name) + '</button></td>' +
          '<td class="c-status">' + statusBadge(e.status) + '</td>' +
          '<td class="c-path">' + esc(pathText(e.categoryId)) + '</td>' +
          '<td class="c-owner">' + esc(e.owner) + '</td>' +
          '<td class="c-tags">' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join('') : '<span class="dim">—</span>') + '</td>' +
          '<td class="c-date">' + esc(e.updatedAt) + '</td></tr>';
        if (open) {
          row += '<tr class="detail"><td></td><td colspan="7"><div class="detail-card">' +
            '<div><b>编码</b><code>' + esc(e.id) + '</code></div>' +
            '<div><b>归属</b>' + esc(pathText(e.categoryId)) + '</div>' +
            '<div><b>状态</b>' + statusBadge(e.status) + '</div>' +
            '<div><b>负责人</b>' + esc(e.owner) + '</div>' +
            '<div><b>标签</b>' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join(' ') : '—') + '</div>' +
            '<div><b>备注</b>' + esc(e.note) + '</div>' +
            '<div><b>更新</b>' + esc(e.updatedAt) + '</div></div></td></tr>';
        }
        return row;
      }).join('');
    }
    // 表头三态复选框
    var visIds = list.map(function (e) { return e.id; });
    var selVis = visIds.filter(function (id) { return state.selection[id]; }).length;
    var head = document.getElementById('head-check');
    head.checked = visIds.length > 0 && selVis === visIds.length;
    head.indeterminate = selVis > 0 && selVis < visIds.length;
    document.getElementById('sel-summary').textContent =
      '已选 ' + selectedIds().length + ' · 可见 ' + visIds.length + ' · 范围内 ' + entitiesInNode(state.scopeNodeId).length;
    // 排序指示
    Array.prototype.forEach.call(document.querySelectorAll('#thead th[data-sort]'), function (th) {
      var on = th.getAttribute('data-sort') === state.sortKey;
      th.setAttribute('aria-sort', on ? (state.sortDir === 1 ? 'ascending' : 'descending') : 'none');
      th.querySelector('.sort-ind').textContent = on ? (state.sortDir === 1 ? '▲' : '▼') : '';
    });
  }

  function renderActionbar() {
    var n = selectedIds().length;
    var bar = document.getElementById('actionbar');
    bar.hidden = n === 0;
    if (!n) return;
    var hidden = hiddenSelected().length;
    document.getElementById('ab-count').innerHTML = '已选 <b>' + n + '</b> 项' +
      (hidden ? ' <span class="ab-hidden">（' + hidden + ' 项当前不可见，仍将包含）</span>' : '');
  }

  function renderStatusbar() {
    var el = document.getElementById('receipt');
    if (state.lastOp && !state.lastOp.undone) {
      el.innerHTML = '<span class="rc-ok">✓</span> ' + esc(state.lastOp.receipt) +
        ' <button class="btn btn-mini" data-act="undo">撤销</button>';
    } else if (state.lastOp && state.lastOp.undone) {
      el.innerHTML = '<span class="dim">已撤销：' + esc(state.lastOp.receipt) + '</span>';
    } else {
      el.innerHTML = '<span class="dim">就绪 · 批量操作经逐项预览确认后生效</span>';
    }
    document.getElementById('ops-btn').textContent = '操作记录 (' + state.ops.length + ')';
    var panel = document.getElementById('ops-panel');
    panel.hidden = !state.opsPanelOpen;
    if (state.opsPanelOpen) {
      panel.innerHTML = state.ops.length
        ? state.ops.slice().reverse().map(function (op) {
          return '<div class="op-item' + (op.undone ? ' undone' : '') + '">' +
            '<span class="op-time">' + esc(op.time) + '</span> ' + esc(op.label) +
            (op.undone ? ' <span class="op-undone">已撤销</span>' : '') + '</div>';
        }).join('')
        : '<div class="dim op-item">暂无操作</div>';
    }
  }

  function renderAll() {
    renderTree();
    renderToolbar();
    renderWarn();
    renderTable();
    renderActionbar();
    renderStatusbar();
  }

  // ---------- 选择集动作（唯一合法入口） ----------
  function addVisible() {
    visibleList().forEach(function (e) { state.selection[e.id] = true; });
    renderAll();
  }
  function addSubtree() {
    entitiesInNode(state.scopeNodeId).forEach(function (e) { state.selection[e.id] = true; });
    renderAll();
  }
  function clearSel() { state.selection = {}; state.anchor = null; renderAll(); }
  function pruneToVisible() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    selectedIds().forEach(function (id) { if (!vis[id]) delete state.selection[id]; });
    renderAll();
  }
  function shiftRange(currentId) {
    var visIds = visibleList().map(function (e) { return e.id; });
    var a = visIds.indexOf(state.anchor), b = visIds.indexOf(currentId);
    if (a === -1 || b === -1) { state.anchor = currentId; return; }
    if (a > b) { var t = a; a = b; b = t; }
    for (var i = a; i <= b; i++) state.selection[visIds[i]] = true;
    renderAll();
  }

  // ---------- 批量操作引擎 ----------
  var OP_META = {
    'status':     { title: '批量修改状态' },
    'move':       { title: '批量移动类别' },
    'tag-add':    { title: '批量添加标签' },
    'tag-remove': { title: '批量移除标签' },
    'delete':     { title: '批量删除实体' }
  };

  function openPreview(type) {
    var ids = selectedIds();
    if (!ids.length) return;
    state.pending = { type: type, ids: ids, target: '', tags: '', confirmDelete: false };
    renderPreviewModal();
    document.getElementById('modal').hidden = false;
    var first = document.querySelector('#modal-ctrl select, #modal-ctrl input[type=text]');
    if (first) first.focus();
  }

  function closePreview() {
    state.pending = null;
    document.getElementById('modal').hidden = true;
  }

  function renderPreviewModal() {
    var p = state.pending;
    if (!p) return;
    document.getElementById('modal-title').textContent = OP_META[p.type].title;

    // 控制区
    var ctrl = document.getElementById('modal-ctrl');
    if (p.type === 'status') {
      ctrl.innerHTML = '<label>目标状态</label><select id="op-target" aria-label="目标状态">' +
        '<option value="">— 选择目标状态 —</option>' +
        STATUSES.map(function (s) {
          return '<option value="' + s.id + '"' + (p.target === s.id ? ' selected' : '') + '>' + s.label + '</option>';
        }).join('') + '</select>';
    } else if (p.type === 'move') {
      var opts = SEED.categories.map(function (c) {
        return '<option value="' + c.id + '"' + (p.target === c.id ? ' selected' : '') + '>' +
          '　'.repeat(c.depth) + esc(c.name) + '（' + esc(CAT_BY_ID[c.domainId].name) + '）</option>';
      }).join('');
      ctrl.innerHTML = '<label>目标类别</label><select id="op-target" aria-label="目标类别">' +
        '<option value="">— 选择目标类别 —</option>' + opts + '</select>';
    } else if (p.type === 'tag-add') {
      ctrl.innerHTML = '<label>新标签（逗号分隔）</label><input type="text" id="op-tags" placeholder="如：待巡检, 核心">';
    } else if (p.type === 'tag-remove') {
      var tagSet = {};
      p.ids.forEach(function (id) { ENT_BY_ID[id].tags.forEach(function (t) { tagSet[t] = true; }); });
      var tagOpts = Object.keys(tagSet).map(function (t) {
        return '<option value="' + esc(t) + '"' + (p.target === t ? ' selected' : '') + '>' + esc(t) + '</option>';
      }).join('');
      ctrl.innerHTML = '<label>要移除的标签</label><select id="op-target" aria-label="要移除的标签">' +
        '<option value="">— 选择标签 —</option>' + tagOpts + '</select>';
    } else {
      ctrl.innerHTML = '<label class="danger-label"><input type="checkbox" id="op-confirm-del"> ' +
        '我确认删除以下 <b>' + p.ids.length + '</b> 项（操作后可撤销）</label>';
    }

    // 控件事件
    var targetSel = document.getElementById('op-target');
    if (targetSel) targetSel.addEventListener('change', function () {
      state.pending.target = this.value;
      renderPreviewModal();
      var s = document.getElementById('op-target');
      if (s) s.focus();
    });
    var tagsInput = document.getElementById('op-tags');
    if (tagsInput) {
      tagsInput.value = p.tags;
      tagsInput.addEventListener('input', function () {
        state.pending.tags = this.value;
        renderPreviewModal();
        var i2 = document.getElementById('op-tags');
        i2.focus();
        i2.setSelectionRange(i2.value.length, i2.value.length);
      });
    }
    var delChk = document.getElementById('op-confirm-del');
    if (delChk) delChk.addEventListener('change', function () {
      state.pending.confirmDelete = this.checked;
      renderPreviewModal();
    });

    // 受影响集合（预览 = 执行的唯一来源）
    var op = pendingOp();
    var aff = op
      ? computeAffected(p.ids, op)
      : { apply: [], noop: p.ids.map(function (id) {
          var e = ENT_BY_ID[id];
          return { id: id, name: e.name, path: pathText(e.categoryId), reason: '尚未选择目标' };
        }) };

    document.getElementById('modal-summary').innerHTML =
      '<span class="mchip">已选 <b>' + p.ids.length + '</b> 项</span>' +
      '<span class="mchip ok">将生效 <b>' + aff.apply.length + '</b> 项</span>' +
      (aff.noop.length ? '<span class="mchip dim2">跳过（无变更）<b>' + aff.noop.length + '</b> 项</span>' : '');

    var rows = aff.apply.map(function (it) {
      var detail = '';
      if (p.type === 'status') detail = statusBadge(it.before) + ' <span class="arrow">→</span> ' + statusBadge(it.after);
      else if (p.type === 'move') detail = '<span class="dim small">' + esc(it.beforePath) + '</span> <span class="arrow">→</span> <span class="small">' + esc(it.afterPath) + '</span>';
      else if (p.type === 'tag-add' || p.type === 'tag-remove') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else detail = statusBadge(it.before) + ' <span class="arrow">→</span> <span class="badge tone-danger">删除</span>';
      return '<div class="aff-row"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change">' + detail + '</span></div>';
    }).join('');
    var noopRows = aff.noop.map(function (it) {
      return '<div class="aff-row noop"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change dim">' + esc(it.reason) + '</span></div>';
    }).join('');
    document.getElementById('modal-list').innerHTML =
      (rows ? '<div class="aff-head">将生效（' + aff.apply.length + '）</div>' + rows : '') +
      (noopRows ? '<div class="aff-head dim-head">跳过——无变更（' + aff.noop.length + '）</div>' + noopRows : '');

    // 错误/可用性
    var err = validatePending();
    document.getElementById('modal-error').textContent = err || '';
    var btn = document.getElementById('btn-confirm');
    btn.disabled = !!err;
    btn.textContent = p.type === 'delete'
      ? '确认删除 ' + aff.apply.length + ' 项'
      : '确认执行（' + aff.apply.length + ' 项）';
  }

  function tagsText(tags, highlight) {
    if (!tags || !tags.length) return '<span class="dim">—</span>';
    return tags.map(function (t) {
      return '<span class="tag' + (highlight ? ' hl' : '') + '">' + esc(t) + '</span>';
    }).join(' ');
  }

  function pendingOp() {
    var p = state.pending;
    if (!p) return null;
    if (p.type === 'status' && p.target) return { type: 'status', target: p.target };
    if (p.type === 'move' && p.target) return { type: 'move', target: p.target };
    if (p.type === 'tag-add') {
      var tags = p.tags.split(/[,，]/).map(function (t) { return t.trim(); }).filter(Boolean);
      return tags.length ? { type: 'tag-add', tags: tags } : null;
    }
    if (p.type === 'tag-remove' && p.target) return { type: 'tag-remove', tag: p.target };
    if (p.type === 'delete') return { type: 'delete' };
    return null;
  }

  function validatePending() {
    var p = state.pending;
    if (!p) return '内部错误';
    var op = pendingOp();
    if (!op) {
      if (p.type === 'delete') return '请先勾选确认框';
      return p.type === 'tag-add' ? '请输入至少一个标签' : '请选择目标';
    }
    var aff = computeAffected(p.ids, op);
    if (!aff.apply.length) return '没有可生效的变更（全部所选实体已处于目标状态/位置）';
    if (p.type === 'delete' && !p.confirmDelete) return '请先勾选确认框';
    return '';
  }

  function confirmOp() {
    var p = state.pending;
    if (!p || validatePending()) return;
    var op = pendingOp();
    var aff = computeAffected(p.ids, op); // 与预览同一函数：作用集合=确认集合
    var time = new Date().toTimeString().slice(0, 8);
    // 快照含全字段，删除也可精确恢复
    var snapshot = aff.apply.map(function (it) {
      var e = it.e;
      return {
        id: e.id, name: e.name, owner: e.owner, note: e.note, updatedAt: e.updatedAt,
        status: e.status, categoryId: e.categoryId, tags: e.tags.slice()
      };
    });
    aff.apply.forEach(function (it) {
      var e = it.e;
      if (op.type === 'status') e.status = op.target;
      else if (op.type === 'move') e.categoryId = op.target;
      else if (op.type === 'tag-add') {
        op.tags.forEach(function (t) { if (e.tags.indexOf(t) === -1) e.tags.push(t); });
      } else if (op.type === 'tag-remove') {
        e.tags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        e._deleted = true;
      }
    });
    if (op.type === 'delete') {
      SEED.entities = SEED.entities.filter(function (e) { return !e._deleted; });
      aff.apply.forEach(function (it) {
        delete ENT_BY_ID[it.id];
        delete state.selection[it.id];
        delete state.detailOpen[it.id];
      });
    }
    var receipt;
    if (op.type === 'status') receipt = '已将 ' + aff.apply.length + ' 项状态改为「' + STATUS_BY_ID[op.target].label + '」';
    else if (op.type === 'move') receipt = '已将 ' + aff.apply.length + ' 项移动到「' + pathText(op.target) + '」';
    else if (op.type === 'tag-add') receipt = '已为 ' + aff.apply.length + ' 项添加标签「' + op.tags.join('、') + '」';
    else if (op.type === 'tag-remove') receipt = '已从 ' + aff.apply.length + ' 项移除标签「' + op.tag + '」';
    else receipt = '已删除 ' + aff.apply.length + ' 项';
    var record = {
      time: time,
      label: OP_META[p.type].title + ' ' + p.ids.length + ' 项',
      receipt: receipt,
      snapshot: snapshot,
      type: op.type,
      undone: false
    };
    state.ops.push(record);
    state.lastOp = record;
    state.pending = null;
    state.selection = {};
    state.anchor = null;
    document.getElementById('modal').hidden = true;
    renderAll();
  }

  function undoLast() {
    var op = state.lastOp;
    if (!op || op.undone) return;
    if (op.type === 'delete') {
      op.snapshot.forEach(function (s) {
        var e = {
          id: s.id, name: s.name, owner: s.owner, note: s.note, updatedAt: s.updatedAt,
          status: s.status, categoryId: s.categoryId, tags: s.tags.slice()
        };
        SEED.entities.push(e);
        ENT_BY_ID[s.id] = e;
      });
    } else {
      op.snapshot.forEach(function (s) {
        var e = ENT_BY_ID[s.id];
        if (!e) return;
        e.status = s.status;
        e.categoryId = s.categoryId;
        e.tags = s.tags.slice();
      });
    }
    op.undone = true;
    state.lastOp = null;
    renderAll();
  }

  // ---------- 事件 ----------
  function treeToggle(id) { state.expanded[id] = !state.expanded[id]; renderAll(); }

  function wire() {
    var tree = document.getElementById('tree');
    tree.addEventListener('click', function (ev) {
      var caret = ev.target.closest('.caret[data-act="caret"]');
      if (caret) { treeToggle(caret.getAttribute('data-id')); return; }
      var row = ev.target.closest('.trow');
      if (!row) return;
      state.scopeNodeId = row.getAttribute('data-id');
      renderAll();
    });
    tree.addEventListener('keydown', function (ev) {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      var row = ev.target.closest('.trow');
      if (!row) return;
      ev.preventDefault();
      state.scopeNodeId = row.getAttribute('data-id');
      renderAll();
    });

    // 工具栏
    document.getElementById('search').addEventListener('input', function () {
      state.query = this.value;
      renderAll();
    });
    document.getElementById('status-chips').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act="status-chip"]');
      if (!b) return;
      var id = b.getAttribute('data-id');
      if (state.statusFilter[id]) delete state.statusFilter[id];
      else state.statusFilter[id] = true;
      renderAll();
    });
    document.getElementById('btn-sel-visible').addEventListener('click', addVisible);
    document.getElementById('btn-sel-subtree').addEventListener('click', addSubtree);
    document.getElementById('btn-clear-filters').addEventListener('click', clearFilters);

    // 警示条
    document.getElementById('warn-strip').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act]');
      if (!b) return;
      var act = b.getAttribute('data-act');
      if (act === 'keep-visible') pruneToVisible();
      else if (act === 'toggle-list') { state.warnListOpen = !state.warnListOpen; renderWarn(); }
    });

    // 表格
    document.getElementById('thead').addEventListener('click', function (ev) {
      var th = ev.target.closest('th[data-sort]');
      if (!th) return;
      var k = th.getAttribute('data-sort');
      if (state.sortKey === k) state.sortDir *= -1;
      else { state.sortKey = k; state.sortDir = 1; }
      renderAll();
    });
    var tbody = document.getElementById('tbody');
    tbody.addEventListener('click', function (ev) {
      if (ev.target.closest('[data-act="clear-filters"]')) { clearFilters(); return; }
      var nameBtn = ev.target.closest('[data-act="detail"]');
      if (nameBtn) {
        var idd = nameBtn.getAttribute('data-id');
        state.detailOpen[idd] = !state.detailOpen[idd];
        renderTable();
        return;
      }
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (chk && ev.shiftKey && state.anchor) {
        ev.preventDefault(); // 范围选择=只加选，不翻转当前框
        shiftRange(chk.getAttribute('data-id'));
      }
    });
    tbody.addEventListener('change', function (ev) {
      var chk = ev.target.closest('input[data-act="row-check"]');
      if (!chk) return;
      var id = chk.getAttribute('data-id');
      if (chk.checked) state.selection[id] = true;
      else delete state.selection[id];
      state.anchor = id;
      renderAll();
    });
    document.getElementById('head-check').addEventListener('click', function () {
      var list = visibleList();
      var allSel = list.length && list.every(function (e) { return state.selection[e.id]; });
      if (allSel) list.forEach(function (e) { delete state.selection[e.id]; });
      else list.forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
    });

    // 操作条
    document.getElementById('actionbar').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-op]');
      if (!b) return;
      openPreview(b.getAttribute('data-op'));
    });
    document.getElementById('btn-ab-clear').addEventListener('click', clearSel);

    // 模态
    document.getElementById('btn-cancel').addEventListener('click', closePreview);
    document.getElementById('btn-confirm').addEventListener('click', confirmOp);
    document.getElementById('modal').addEventListener('click', function (ev) {
      if (ev.target === document.getElementById('modal')) closePreview();
    });

    // 状态栏
    document.getElementById('statusbar').addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-act]');
      if (!b) return;
      var act = b.getAttribute('data-act');
      if (act === 'undo') undoLast();
      else if (act === 'toggle-ops') { state.opsPanelOpen = !state.opsPanelOpen; renderStatusbar(); }
    });

    // 键盘契约：/ 聚焦搜索；Esc 关闭模态
    document.addEventListener('keydown', function (ev) {
      var tag = document.activeElement ? document.activeElement.tagName : '';
      if (ev.key === '/' && !/INPUT|SELECT|TEXTAREA/.test(tag)) {
        ev.preventDefault();
        document.getElementById('search').focus();
      }
      if (ev.key === 'Escape' && state.pending) closePreview();
    });

    window.addEventListener('error', function (e) {
      var el = document.getElementById('errbanner');
      el.hidden = false;
      el.textContent = '运行错误：' + (e.message || '未知错误');
    });
  }

  function clearFilters() {
    state.query = '';
    state.statusFilter = {};
    state.scopeNodeId = 'root';
    document.getElementById('search').value = '';
    renderAll();
  }

  // ---------- 演示场景（供自动化截图取证；不影响正常使用） ----------
  function runScene() {
    var m = /scene=(\w+)/.exec(location.search);
    if (!m) return;
    var scene = m[1];
    if (scene === 'selected') {
      // 选中「产线设备」子树全部，再只显示「在用」→ 隐藏已选警示 + 操作条
      entitiesInNode('c3').forEach(function (e) { state.selection[e.id] = true; });
      state.statusFilter = { active: true };
      renderAll();
    } else if (scene === 'preview') {
      entitiesInNode('c11').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('status');
      state.pending.target = 'disabled';
      renderPreviewModal();
    } else if (scene === 'delete') {
      entitiesInNode('c34').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
      openPreview('delete');
    } else if (scene === 'detail') {
      var first = visibleList()[0];
      if (first) state.detailOpen[first.id] = true;
      entitiesInNode('c21').forEach(function (e) { state.selection[e.id] = true; });
      renderAll();
    }
  }

  // ---------- 启动：同步就绪，无加载态 ----------
  wire();
  renderAll();
  runScene();
})();

tool_use_result.originalFile:
/* cell-j01-s01 实体目录管理台 — 应用核心
 * 架构：单一数据源（内存实体数组）+ 派生渲染；
 * 状态归属：selection（选择集）/ query（筛选器）/ mode（预览模态）/ viewport（树展开）四类状态各有唯一属主。
 * 零误伤契约：computeAffected() 是预览与执行的唯一共同来源——确认列表与实际作用集合逐 id 一致。 */
(function () {
  'use strict';

  var SEED = window.SEED;
  var STATUSES = SEED.statuses;
  var STATUS_BY_ID = {};
  STATUSES.forEach(function (s) { STATUS_BY_ID[s.id] = s; });

  // ---------- 索引 ----------
  var CAT_BY_ID = {};
  SEED.categories.forEach(function (c) { CAT_BY_ID[c.id] = c; });
  var CHILDREN = {};
  SEED.categories.forEach(function (c) {
    if (c.parentId) { (CHILDREN[c.parentId] = CHILDREN[c.parentId] || []).push(c); }
  });
  var DOMAIN_CATS = {};
  SEED.categories.forEach(function (c) {
    if (!c.parentId) { (DOMAIN_CATS[c.domainId] = DOMAIN_CATS[c.domainId] || []).push(c); }
  });
  var ENT_BY_ID = {};
  SEED.entities.forEach(function (e) { ENT_BY_ID[e.id] = e; });

  // ---------- 状态（各有唯一属主） ----------
  var state = {
    // query —— 筛选器：只决定可见行，永不触碰 selection
    scopeNodeId: 'root',
    query: '',
    statusFilter: {},        // {statusId:true}
    sortKey: 'id',
    sortDir: 1,
    // selection —— 选择集：仅 行复选 / 范围全选 / 清空 / 仅保留可见 四种显式动作可变
    selection: {},           // {entityId:true}
    // viewport —— 树展开状态
    expanded: { root: true },
    // mode —— 预览确认模态（暂存待执行操作）
    pending: null,
    // 操作记录
    ops: [],
    lastOp: null,
    // 交互辅助
    anchor: null,            // shift 范围选择锚点
    detailOpen: {},          // 行内展开
    warnListOpen: false,
    opsPanelOpen: false
  };

  SEED.domains.forEach(function (d) { state.expanded[d.id] = true; });
  SEED.categories.forEach(function (c) { if (c.depth <= 1) state.expanded[c.id] = true; });

  // ---------- 纯派生 ----------
  function allEntities() { return SEED.entities; }

  function catPath(catId) {
    var parts = [], c = CAT_BY_ID[catId];
    while (c) { parts.unshift(c.name); c = c.parentId ? CAT_BY_ID[c.parentId] : null; }
    return parts;
  }
  function pathText(catId) { return catPath(catId).join(' / '); }
  function statusOf(e) { return STATUS_BY_ID[e.status]; }

  function subtreeCatIds(nodeId) {
    if (nodeId === 'root') return SEED.categories.map(function (c) { return c.id; });
    var out = [nodeId], queue = [nodeId];
    while (queue.length) {
      var cur = queue.shift();
      (CHILDREN[cur] || []).forEach(function (ch) { out.push(ch.id); queue.push(ch.id); });
    }
    return out;
  }

  function entitiesInNode(nodeId) {
    var ids = subtreeCatIds(nodeId), set = {};
    ids.forEach(function (id) { set[id] = true; });
    return allEntities().filter(function (e) { return set[e.categoryId]; });
  }

  function visibleList() {
    var q = state.query.trim().toLowerCase();
    var scopeIds = subtreeCatIds(state.scopeNodeId), scopeSet = {};
    scopeIds.forEach(function (id) { scopeSet[id] = true; });
    var list = allEntities().filter(function (e) {
      if (!scopeSet[e.categoryId]) return false;
      if (state.statusFilter[e.status]) {
        // 状态筛选语义：勾选的状态=排除该状态（筛选chip显示为「隐藏 xx」）？
        // —— 采用「显示所选状态」的常规语义：见下方判断
      }
      return true;
    });
    // 状态筛选：未勾选任何状态 = 全部显示；有勾选 = 只显示勾选状态
    var active = STATUSES.some(function (s) { return state.statusFilter[s.id]; });
    if (active) list = list.filter(function (e) { return state.statusFilter[e.status]; });
    if (q) {
      list = list.filter(function (e) {
        return (e.id + ' ' + e.name + ' ' + e.owner + ' ' + e.tags.join(' ') + ' ' + pathText(e.categoryId))
          .toLowerCase().indexOf(q) !== -1;
      });
    }
    var k = state.sortKey, dir = state.sortDir;
    list.sort(function (a, b) {
      var va, vb;
      if (k === 'status') { va = statusOf(a).label; vb = statusOf(b).label; }
      else if (k === 'path') { va = pathText(a.categoryId); vb = pathText(b.categoryId); }
      else { va = a[k]; vb = b[k]; }
      return va < vb ? -dir : va > vb ? dir : (a.id < b.id ? -1 : 1);
    });
    return list;
  }

  // 节点聚合：直接计数 / 累计计数 / 状态分布（树、表格、状态栏三处同源）
  function nodeAgg(nodeId) {
    var list = entitiesInNode(nodeId);
    var dist = {};
    STATUSES.forEach(function (s) { dist[s.id] = 0; });
    list.forEach(function (e) { dist[e.status] += 1; });
    return { total: list.length, dist: dist };
  }

  function selectedIds() {
    return Object.keys(state.selection);
  }
  function hiddenSelected() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    return selectedIds().filter(function (id) { return !vis[id]; });
  }

  // ---------- 零误伤核心：预览与执行共用同一计算 ----------
  // 返回 {apply:[{id,before,after}], noop:[{id,reason}]}
  function computeAffected(ids, op) {
    var apply = [], noop = [];
    ids.forEach(function (id) {
      var e = ENT_BY_ID[id];
      var item = { id: id, name: e.name, path: pathText(e.categoryId), e: e };
      if (op.type === 'status') {
        if (e.status === op.target) { item.reason = '已是「' + statusOf(e).label + '」'; noop.push(item); return; }
        item.before = e.status; item.after = op.target;
      } else if (op.type === 'move') {
        if (e.categoryId === op.target) { item.reason = '已在该类别'; noop.push(item); return; }
        item.beforePath = pathText(e.categoryId); item.afterPath = pathText(op.target);
      } else if (op.type === 'tag-add') {
        var add = op.tags.filter(function (t) { return e.tags.indexOf(t) === -1; });
        if (!add.length) { item.reason = '已含全部目标标签'; noop.push(item); return; }
        item.beforeTags = e.tags.slice(); item.afterTags = e.tags.concat(add);
      } else if (op.type === 'tag-remove') {
        if (e.tags.indexOf(op.tag) === -1) { item.reason = '不含标签「' + op.tag + '」'; noop.push(item); return; }
        item.beforeTags = e.tags.slice();
        item.afterTags = e.tags.filter(function (t) { return t !== op.tag; });
      } else if (op.type === 'delete') {
        item.before = e.status;
      }
      apply.push(item);
    });
    return { apply: apply, noop: noop };
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // ---------- 渲染 ----------
  var $ = function (sel) { return document.querySelector(sel); };

  function statusBadge(sid, extra) {
    var s = STATUS_BY_ID[sid];
    return '<span class="badge tone-' + s.tone + (extra ? ' ' + extra : '') + '">' + s.label + '</span>';
  }

  function renderTree() {
    var host = $('#tree');
    var html = treeNode('root', '全部实体', null, 0);
    SEED.domains.forEach(function (d) {
      var kids = DOMAIN_CATS[d.id] || [];
      var inner = kids.map(function (c) { return catNode(c, 1); }).join('');
      html += domainNode(d, inner);
    });
    host.innerHTML = html;
  }

  function domainNode(d, inner) {
    var agg = nodeAgg(d.id);
    var open = !!state.expanded[d.id];
    return '<div class="tnode depth-0' + (state.scopeNodeId === d.id ? ' scoped' : '') + '" data-node="' + d.id + '">' +
      '<div class="trow" role="treeitem" aria-expanded="' + open + '" tabindex="0" data-act="toggle" data-id="' + d.id + '">' +
      '<span class="caret' + (open ? ' open' : '') + '">▸</span>' +
      '<span class="tname">' + esc(d.name) + '</span>' + countsHtml(agg) + microBar(agg) + '</div>' +
      (open ? '<div class="tkids">' + inner + '</div>' : '') +
      '</div>';
  }

  function catNode(c, depth) {
    var agg = nodeAgg(c.id);
    var kids = CHILDREN[c.id] || [];
    var open = !!state.expanded[c.id];
    var row = '<div class="trow' + (state.scopeNodeId === c.id ? ' scoped' : '') + '" role="treeitem" tabindex="0"' +
      (kids.length ? ' aria-expanded="' + open + '"' : '') +
      ' data-act="' + (kids.length ? 'toggle' : 'scope') + '" data-id="' + c.id + '">' +
      (kids.length ? '<span class="caret' + (open ? ' open' : '') + '">▸</span>' : '<span class="caret leaf"></span>') +
      '<span class="tname">' + esc(c.name) + '</span>' + countsHtml(agg) + microBar(agg) + '</div>';
    var childHtml = kids.length && open ? '<div class="tkids">' + kids.map(function (ch) { return catNode(ch, depth + 1); }).join('') + '</div>' : '';
    return '<div class="tnode depth-' + depth + '">' + row + childHtml + '</div>';
  }

  function treeNode(id, name, aggIgnored, depth) {
    var agg = nodeAgg(id === 'root' ? 'root' : id);
    var list = id === 'root' ? { total: agg.total } : agg;
    return '<div class="tnode depth-0' + (state.scopeNodeId === 'root' ? ' scoped' : '') + '" data-node="root">' +
      '<div class="trow" role="treeitem" tabindex="0" data-act="scope" data-id="root">' +
      '<span class="caret leaf"></span><span class="tname">' + esc(name) + '</span>' +
      countsHtml({ total: agg.total }) + microBar(agg) + '</div></div>';
  }

  function countsHtml(agg) {
    var direct = agg ? agg.total : 0;
    return '<span class="tcount">' + direct + '</span>';
  }

  function microBar(agg) {
    if (!agg || !agg.total) return '<span class="mbar" title="无实体"></span>';
    var segs = STATUSES.map(function (s) {
      var n = agg.dist[s.id];
      return n ? '<i class="tone-' + s.tone + '" style="flex:' + n + '" title="' + s.label + ' ' + n + '"></i>' : '';
    }).join('');
    return '<span class="mbar">' + segs + '</span>';
  }

  function renderToolbar() {
    var scopeName = state.scopeNodeId === 'root' ? '全部实体'
      : pathText(state.scopeNodeId);
    $('#scope-crumb').textContent = '范围：' + scopeName + '（含子层级）';
    var vis = visibleList().length;
    var sub = entitiesInNode(state.scopeNodeId).length;
    $('#btn-sel-visible').textContent = '选当前筛选结果 (' + vis + ')';
    $('#btn-sel-subtree').textContent = '选子树全部 (' + sub + ')';
    // 状态 chips（全局计数，点击=只显示该状态）
    var distAll = {};
    STATUSES.forEach(function (s) { distAll[s.id] = 0; });
    allEntities().forEach(function (e) { distAll[e.status] += 1; });
    $('#status-chips').innerHTML = STATUSES.map(function (s) {
      var on = !!state.statusFilter[s.id];
      return '<button class="chip tone-' + s.tone + (on ? ' on' : '') + '" data-act="status-chip" data-id="' + s.id + '"' +
        ' aria-pressed="' + on + '" title="' + (on ? '取消筛选' : '只显示') + '「' + s.label + '」">' +
        s.label + ' <b>' + distAll[s.id] + '</b></button>';
    }).join('');
  }

  function renderWarn() {
    var hidden = hiddenSelected();
    var el = $('#warn');
    if (!hidden.length) { el.hidden = true; state.warnListOpen = false; $('#warn-list').hidden = true; return; }
    el.hidden = false;
    $('#warn-text').textContent = '已选 ' + selectedIds().length + ' 项中有 ' + hidden.length +
      ' 项被当前筛选/范围隐藏——批量操作仍会包含它们。';
    var listEl = $('#warn-list');
    listEl.hidden = !state.warnListOpen;
    if (state.warnListOpen) {
      listEl.innerHTML = hidden.map(function (id) {
        var e = ENT_BY_ID[id];
        return '<div class="warn-item"><code>' + esc(id) + '</code> ' + esc(e.name) +
          ' <span class="dim">· ' + esc(pathText(e.categoryId)) + '</span></div>';
      }).join('');
    }
  }

  function renderTable() {
    var list = visibleList();
    var tbody = $('#tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr class="empty-row"><td colspan="8"><div class="empty">' +
        '<div class="empty-title">当前范围内没有匹配的实体</div>' +
        '<div class="dim">调整关键字或状态筛选，或<span class="link" data-act="clear-filters" tabindex="0">清除全部筛选</span></div>' +
        '</div></td></tr>';
    } else {
      tbody.innerHTML = list.map(function (e) {
        var sel = !!state.selection[e.id];
        var open = !!state.detailOpen[e.id];
        var row = '<tr class="ent' + (sel ? ' sel' : '') + '" data-id="' + e.id + '">' +
          '<td class="c-check"><input type="checkbox" data-act="row-check" data-id="' + e.id + '"' +
          (sel ? ' checked' : '') + ' aria-label="选择 ' + esc(e.name) + '"></td>' +
          '<td class="c-code"><code>' + esc(e.id) + '</code></td>' +
          '<td class="c-name"><button class="name-btn" data-act="detail" data-id="' + e.id + '" aria-expanded="' + open + '">' +
          '<span class="chev">' + (open ? '▾' : '▸') + '</span>' + esc(e.name) + '</button></td>' +
          '<td class="c-status">' + statusBadge(e.status) + '</td>' +
          '<td class="c-path">' + esc(pathText(e.categoryId)) + '</td>' +
          '<td class="c-owner">' + esc(e.owner) + '</td>' +
          '<td class="c-tags">' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join('') : '<span class="dim">—</span>') + '</td>' +
          '<td class="c-date">' + esc(e.updatedAt) + '</td></tr>';
        if (open) {
          row += '<tr class="detail"><td></td><td colspan="7"><div class="detail-card">' +
            '<div><b>编码</b><code>' + esc(e.id) + '</code></div>' +
            '<div><b>归属</b>' + esc(pathText(e.categoryId)) + '</div>' +
            '<div><b>状态</b>' + statusBadge(e.status) + '</div>' +
            '<div><b>负责人</b>' + esc(e.owner) + '</div>' +
            '<div><b>标签</b>' + (e.tags.length ? e.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join(' ') : '—') + '</div>' +
            '<div><b>备注</b>' + esc(e.note) + '</div>' +
            '<div><b>更新</b>' + esc(e.updatedAt) + '</div></div></td></tr>';
        }
        return row;
      }).join('');
    }
    // 表头三态复选框
    var visIds = list.map(function (e) { return e.id; });
    var selVis = visIds.filter(function (id) { return state.selection[id]; }).length;
    var head = $('#head-check');
    head.checked = visIds.length > 0 && selVis === visIds.length;
    head.indeterminate = selVis > 0 && selVis < visIds.length;
    $('#sel-summary').textContent = '已选 ' + selectedIds().length + ' · 可见 ' + visIds.length + ' · 范围内 ' + entitiesInNode(state.scopeNodeId).length;
    // 排序指示
    document.querySelectorAll('#thead th[data-sort]').forEach(function (th) {
      var on = th.getAttribute('data-sort') === state.sortKey;
      th.setAttribute('aria-sort', on ? (state.sortDir === 1 ? 'ascending' : 'descending') : 'none');
      var el = th.querySelector('.sort-ind');
      el.textContent = on ? (state.sortDir === 1 ? '▲' : '▼') : '';
    });
  }

  function renderActionbar() {
    var n = selectedIds().length;
    var bar = $('#actionbar');
    bar.hidden = n === 0;
    if (!n) return;
    var hidden = hiddenSelected().length;
    $('#ab-count').innerHTML = '已选 <b>' + n + '</b> 项' +
      (hidden ? ' <span class="ab-hidden">（' + hidden + ' 项当前不可见，仍将包含）</span>' : '');
  }

  function renderStatusbar() {
    var el = $('#receipt');
    if (state.lastOp && !state.lastOp.undone) {
      el.innerHTML = '<span class="rc-ok">✓</span> ' + esc(state.lastOp.receipt) +
        ' <button class="btn btn-mini" data-act="undo">撤销</button>';
    } else if (state.lastOp && state.lastOp.undone) {
      el.innerHTML = '<span class="dim">已撤销：' + esc(state.lastOp.receipt) + '</span>';
    } else {
      el.innerHTML = '<span class="dim">就绪 · 批量操作经逐项预览确认后生效</span>';
    }
    $('#ops-btn').textContent = '操作记录 (' + state.ops.length + ')';
    var panel = $('#ops-panel');
    panel.hidden = !state.opsPanelOpen;
    if (state.opsPanelOpen) {
      panel.innerHTML = state.ops.length
        ? state.ops.slice().reverse().map(function (op) {
          return '<div class="op-item' + (op.undone ? ' undone' : '') + '">' +
            '<span class="op-time">' + esc(op.time) + '</span> ' + esc(op.label) +
            (op.undone ? ' <span class="op-undone">已撤销</span>' : '') + '</div>';
        }).join('')
        : '<div class="dim op-item">暂无操作</div>';
    }
  }

  function renderAll() {
    renderTree();
    renderToolbar();
    renderWarn();
    renderTable();
    renderActionbar();
    renderStatusbar();
  }

  // ---------- 选择集动作（唯一合法入口） ----------
  function addVisible() { visibleList().forEach(function (e) { state.selection[e.id] = true; }); renderAll(); }
  function addSubtree() { entitiesInNode(state.scopeNodeId).forEach(function (e) { state.selection[e.id] = true; }); renderAll(); }
  function clearSel() { state.selection = {}; state.anchor = null; renderAll(); }
  function pruneToVisible() {
    var vis = {};
    visibleList().forEach(function (e) { vis[e.id] = true; });
    selectedIds().forEach(function (id) { if (!vis[id]) delete state.selection[id]; });
    renderAll();
  }

  function shiftRange(currentId, shift) {
    if (!shift || !state.anchor) { state.anchor = currentId; return false; }
    var visIds = visibleList().map(function (e) { return e.id; });
    var a = visIds.indexOf(state.anchor), b = visIds.indexOf(currentId);
    if (a === -1 || b === -1) { state.anchor = currentId; return false; }
    if (a > b) { var t = a; a = b; b = t; }
    for (var i = a; i <= b; i++) state.selection[visIds[i]] = true;
    renderAll();
    return true;
  }

  // ---------- 批量操作引擎 ----------
  var OP_META = {
    'status':     { title: '批量修改状态', need: 'target-status' },
    'move':       { title: '批量移动类别', need: 'target-cat' },
    'tag-add':    { title: '批量添加标签', need: 'tags' },
    'tag-remove': { title: '批量移除标签', need: 'tag' },
    'delete':     { title: '批量删除实体', need: 'confirm-delete' }
  };

  function openPreview(type) {
    var ids = selectedIds();
    if (!ids.length) return;
    state.pending = { type: type, ids: ids, target: '', tags: '', confirmDelete: false };
    renderPreviewModal();
    $('#modal').hidden = false;
    var first = $('#modal').querySelector('select,input[type=text]');
    if (first) first.focus();
  }

  function closePreview() {
    state.pending = null;
    $('#modal').hidden = true;
  }

  function renderPreviewModal() {
    var p = state.pending;
    if (!p) return;
    var meta = OP_META[p.type];
    $('#modal-title').textContent = meta.title;

    // 控制区
    var ctrl = $('#modal-ctrl');
    if (p.type === 'status') {
      ctrl.innerHTML = '<label>目标状态</label><select id="op-target" aria-label="目标状态">' +
        '<option value="">— 选择目标状态 —</option>' +
        STATUSES.map(function (s) {
          return '<option value="' + s.id + '"' + (p.target === s.id ? ' selected' : '') + '>' + s.label + '</option>';
        }).join('') + '</select>';
    } else if (p.type === 'move') {
      var opts = [];
      SEED.categories.forEach(function (c) {
        opts.push('<option value="' + c.id + '"' + (p.target === c.id ? ' selected' : '') + '>' +
          '　'.repeat(c.depth) + esc(c.name) + '（' + esc(CAT_BY_ID[c.domainId].name) + '）</option>');
      });
      ctrl.innerHTML = '<label>目标类别</label><select id="op-target" aria-label="目标类别">' +
        '<option value="">— 选择目标类别 —</option>' + opts.join('') + '</select>';
    } else if (p.type === 'tag-add') {
      ctrl.innerHTML = '<label>新标签（逗号分隔）</label><input type="text" id="op-tags" placeholder="如：待巡检, 核心">' ;
    } else if (p.type === 'tag-remove') {
      var tagSet = {};
      p.ids.forEach(function (id) { ENT_BY_ID[id].tags.forEach(function (t) { tagSet[t] = true; }); });
      var tagOpts = Object.keys(tagSet).map(function (t) {
        return '<option value="' + esc(t) + '"' + (p.target === t ? ' selected' : '') + '>' + esc(t) + '</option>';
      }).join('');
      ctrl.innerHTML = '<label>要移除的标签</label><select id="op-target" aria-label="要移除的标签">' +
        '<option value="">— 选择标签 —</option>' + tagOpts + '</select>';
    } else {
      ctrl.innerHTML = '<label class="danger-label"><input type="checkbox" id="op-confirm-del"> ' +
        '我确认删除以下 <b>' + p.ids.length + '</b> 项（操作后可撤销）</label>';
    }

    // 目标值回填
    var targetSel = $('#op-target');
    if (targetSel) targetSel.addEventListener('change', function () { state.pending.target = this.value; renderPreviewModal(); var s = $('#op-target'); if (s) s.focus(); });
    var tagsInput = $('#op-tags');
    if (tagsInput) {
      tagsInput.value = p.tags;
      tagsInput.addEventListener('input', function () { state.pending.tags = this.value; renderPreviewModal(); var i2 = $('#op-tags'); i2.focus(); i2.setSelectionRange(i2.value.length, i2.value.length); });
    }
    var delChk = $('#op-confirm-del');
    if (delChk) delChk.addEventListener('change', function () { state.pending.confirmDelete = this.checked; renderPreviewModal(); });

    // 受影响集合（预览 = 执行的唯一来源）
    var op = pendingOp();
    var aff = op ? computeAffected(p.ids, op) : { apply: [], noop: p.ids.map(function (id) {
      var e = ENT_BY_ID[id]; return { id: id, name: e.name, path: pathText(e.categoryId), reason: '尚未选择目标' };
    }) };
    state.pending._aff = aff;

    $('#modal-summary').innerHTML =
      '<span class="mchip">已选 <b>' + p.ids.length + '</b> 项</span>' +
      '<span class="mchip ok">将生效 <b>' + aff.apply.length + '</b> 项</span>' +
      (aff.noop.length ? '<span class="mchip dim">跳过（无变更）<b>' + aff.noop.length + '</b> 项</span>' : '');

    var listEl = $('#modal-list');
    var rows = aff.apply.map(function (it) {
      var detail = '';
      if (p.type === 'status') detail = statusBadge(it.before) + ' <span class="arrow">→</span> ' + statusBadge(it.after);
      else if (p.type === 'move') detail = '<span class="dim">' + esc(it.beforePath) + '</span> <span class="arrow">→</span> ' + esc(it.afterPath);
      else if (p.type === 'tag-add') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else if (p.type === 'tag-remove') detail = '<span class="dim">' + tagsText(it.beforeTags) + '</span> <span class="arrow">→</span> ' + tagsText(it.afterTags, true);
      else detail = statusBadge(it.before) + ' <span class="arrow">→</span> <span class="badge tone-danger">删除</span>';
      return '<div class="aff-row"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change">' + detail + '</span></div>';
    }).join('');
    var noopRows = aff.noop.map(function (it) {
      return '<div class="aff-row noop"><code>' + esc(it.id) + '</code><span class="aff-name">' + esc(it.name) + '</span>' +
        '<span class="aff-path dim">' + esc(it.path) + '</span><span class="aff-change dim">' + esc(it.reason) + '</span></div>';
    }).join('');
    listEl.innerHTML =
      (rows ? '<div class="aff-head">将生效（' + aff.apply.length + '）</div>' + rows : '') +
      (noopRows ? '<div class="aff-head dim-head">跳过——无变更（' + aff.noop.length + '）</div>' + noopRows : '') ||
      '<div class="dim aff-row">没有可选实体</div>';

    // 错误/可用性
    var err = validatePending();
    $('#modal-error').textContent = err || '';
    $('#btn-confirm').disabled = !!err;
    $('#btn-confirm').textContent = p.type === 'delete' ? '确认删除 ' + aff.apply.length + ' 项' : '确认执行（' + aff.apply.length + ' 项）';
  }

  function tagsText(tags, highlightDiff) {
    if (!tags || !tags.length) return '<span class="dim">—</span>';
    return tags.map(function (t) { return '<span class="tag' + (highlightDiff ? ' hl' : '') + '">' + esc(t) + '</span>'; }).join(' ');
  }

  function pendingOp() {
    var p = state.pending;
    if (!p) return null;
    if (p.type === 'status' && p.target) return { type: 'status', target: p.target };
    if (p.type === 'move' && p.target) return { type: 'move', target: p.target };
    if (p.type === 'tag-add') {
      var tags = p.tags.split(/[,，]/).map(function (t) { return t.trim(); }).filter(Boolean);
      return tags.length ? { type: 'tag-add', tags: tags } : null;
    }
    if (p.type === 'tag-remove' && p.target) return { type: 'tag-remove', tag: p.target };
    if (p.type === 'delete') return { type: 'delete' };
    return null;
  }

  function validatePending() {
    var p = state.pending;
    if (!p) return '内部错误';
    var op = pendingOp();
    if (!op) {
      if (p.type === 'delete') return '请先勾选确认框';
      return p.type === 'tag-add' ? '请输入至少一个标签' : '请选择目标';
    }
    var aff = computeAffected(p.ids, op);
    if (!aff.apply.length) return '没有可生效的变更（全部所选实体已处于目标状态/位置）';
    if (p.type === 'delete' && !p.confirmDelete) return '请先勾选确认框';
    return '';
  }

  function confirmOp() {
    var p = state.pending;
    if (!p || validatePending()) return;
    var op = pendingOp();
    var aff = computeAffected(p.ids, op); // 再次计算 = 与预览同一函数；此处 aff 与 state.pending._aff 同源
    var time = new Date().toTimeString().slice(0, 8);
    var snapshot = aff.apply.map(function (it) {
      var e = it.e;
      return { id: it.id, status: e.status, categoryId: e.categoryId, tags: e.tags.slice() };
    });
    aff.apply.forEach(function (it) {
      var e = it.e;
      if (op.type === 'status') e.status = op.target;
      else if (op.type === 'move') e.categoryId = op.target;
      else if (op.type === 'tag-add') { op.tags.forEach(function (t) { if (e.tags.indexOf(t) === -1) e.tags.push(t); }); }
      else if (op.type === 'tag-remove') { e.tags = e.tags.filter(function (t) { return t !== op.tag; }); }
      else if (op.type === 'delete') { e._deleted = true; }
    });
    if (op.type === 'delete') {
      SEED.entities = SEED.entities.filter(function (e) { return !e._deleted; });
      aff.apply.forEach(function (it) { delete ENT_BY_ID[it.id]; delete state.selection[it.id]; delete state.detailOpen[it.id]; });
    }
    var label = OP_META[p.type].title;
    var receipt;
    if (op.type === 'status') receipt = '已将 ' + aff.apply.length + ' 项状态改为「' + STATUS_BY_ID[op.target].label + '」';
    else if (op.type === 'move') receipt = '已将 ' + aff.apply.length + ' 项移动到「' + pathText(op.target) + '」';
    else if (op.type === 'tag-add') receipt = '已为 ' + aff.apply.length + ' 项添加标签「' + op.tags.join('、') + '」';
    else if (op.type === 'tag-remove') receipt = '已从 ' + aff.apply.length + ' 项移除标签「' + op.tag + '」';
    else receipt = '已删除 ' + aff.apply.length + ' 项';
    var record = { time: time, label: label + ' ' + p.ids.length + ' 项', receipt: receipt, snapshot: snapshot, undone: false, type: op.type, restore: op.type === 'delete' ? snapshot : null };
    state.ops.push(record);
    state.lastOp = record;
    state.pending = null;
    state.selection = {};
    state.anchor = null;
    $('#modal').hidden = true;
    renderAll();
  }

  function undoLast() {
    var op = state.lastOp;
    if (!op || op.undone) return;
    if (op.type === 'delete') {
      op.snapshot.forEach(function (s) {
        var e = { id: s.id, status: s.status, categoryId: s.categoryId, tags: s.tags, name: s.name, owner: s.owner, note: s.note, updatedAt: s.updatedAt };
        SEED.entities.push(e);
        ENT_BY_ID[s.id] = e;
      });
      // delete 快照需含全部字段：见 makeSnapshot 增强
    } else {
      op.snapshot.forEach(function (s) {
