.chip.tone-warn { color: var(--warn); }  .chip.tone-warn b, .chip.tone-warn.on { background: var(--warn-bg); }
.chip.tone-muted { color: var(--muted); }.chip.tone-muted b, .chip.tone-muted.on { background: var(--muted-bg); }
.chip.tone-danger { color: var(--danger); }.chip.tone-danger b, .chip.tone-danger.on { background: var(--danger-bg); }
#sel-summary { margin-left: auto; font-size: 12px; color: var(--ink-2); }

