57	  function catPath(catId) {
58	    var parts = [], c = CAT_BY_ID[catId];
59	    while (c) { parts.unshift(c.name); c = c.parentId ? CAT_BY_ID[c.parentId] : null; }
60	    return parts;
61	  }
62	  function pathText(catId) { return catPath(catId).join(' / '); }
63	  function statusOf(e) { return STATUS_BY_ID[e.status]; }
64	
65	  function subtreeCatIds(nodeId) {
66	    if (nodeId === 'root') return SEED.categories.map(function (c) { return c.id; });
67	    var out = [nodeId], queue = [nodeId];
68	    while (queue.length) {
69	      var cur = queue.shift();
70	      (CHILDREN[cur] || []).forEach(function (ch) { out.push(ch.id); queue.push(ch.id); });
71	    }
72	    return out;
73	  }
74	
75	  function entitiesInNode(nodeId) {
76	    var ids = subtreeCatIds(nodeId), set = {};
77	    ids.forEach(function (id) { set[id] = true; });
78	    return allEntities().filter(function (e) { return set[e.categoryId]; });
79	  }
