81	  function visibleList() {
82	    var q = state.query.trim().toLowerCase();
83	    var scopeIds = subtreeCatIds(state.scopeNodeId), scopeSet = {};
84	    scopeIds.forEach(function (id) { scopeSet[id] = true; });
85	    // 状态筛选：未勾选任何状态 = 全部显示；有勾选 = 只显示勾选状态
86	    var anyFilter = STATUSES.some(function (s) { return state.statusFilter[s.id]; });
87	    var list = allEntities().filter(function (e) {
88	      if (!scopeSet[e.categoryId]) return false;
89	      if (anyFilter && !state.statusFilter[e.status]) return false;
90	      return true;
91	    });
92	    if (q) {
93	      list = list.filter(function (e) {
94	        return (e.id + ' ' + e.name + ' ' + e.owner + ' ' + e.tags.join(' ') + ' ' + pathText(e.categoryId))
95	          .toLowerCase().indexOf(q) !== -1;
96	      });
97	    }
98	    var k = state.sortKey, dir = state.sortDir;
99	    list.sort(function (a, b) {
100	      var va, vb;
101	      if (k === 'status') { va = statusOf(a).label; vb = statusOf(b).label; }
102	      else if (k === 'path') { va = pathText(a.categoryId); vb = pathText(b.categoryId); }
103	      else { va = a[k]; vb = b[k]; }
104	      return va < vb ? -dir : va > vb ? dir : (a.id < b.id ? -1 : 1);
105	    });
106	    return list;
107	  }
