109	  // 节点聚合：直接计数 / 累计计数 / 状态分布（树、表格、状态栏三处同源）
110	  function nodeAgg(nodeId) {
111	    var direct = nodeId === 'root' ? 0
112	      : allEntities().filter(function (e) { return e.categoryId === nodeId; }).length;
113	    var list = entitiesInNode(nodeId);
114	    var dist = {};
115	    STATUSES.forEach(function (s) { dist[s.id] = 0; });
116	    list.forEach(function (e) { dist[e.status] += 1; });
117	    return { total: list.length, direct: direct, dist: dist };
118	  }
