129	  // ---------- 零误伤核心：预览与执行共用同一计算 ----------
130	  // 返回 {apply:[{id,name,path,before,after,...}], noop:[{id,name,path,reason}]}
131	  function computeAffected(ids, op) {
132	    var apply = [], noop = [];
133	    ids.forEach(function (id) {
134	      var e = ENT_BY_ID[id];
135	      var item = { id: id, name: e.name, path: pathText(e.categoryId), e: e };
136	      if (op.type === 'status') {
137	        if (e.status === op.target) { item.reason = '已是「' + statusOf(e).label + '」'; noop.push(item); return; }
138	        item.before = e.status; item.after = op.target;
139	      } else if (op.type === 'move') {
140	        if (e.categoryId === op.target) { item.reason = '已在该类别'; noop.push(item); return; }
141	        item.beforePath = pathText(e.categoryId); item.afterPath = pathText(op.target);
142	      } else if (op.type === 'tag-add') {
143	        var add = op.tags.filter(function (t) { return e.tags.indexOf(t) === -1; });
144	        if (!add.length) { item.reason = '已含全部目标标签'; noop.push(item); return; }
145	        item.beforeTags = e.tags.slice(); item.afterTags = e.tags.concat(add);
146	      } else if (op.type === 'tag-remove') {
147	        if (e.tags.indexOf(op.tag) === -1) { item.reason = '不含标签「' + op.tag + '」'; noop.push(item); return; }
148	        item.beforeTags = e.tags.slice();
149	        item.afterTags = e.tags.filter(function (t) { return t !== op.tag; });
150	      } else if (op.type === 'delete') {
151	        item.before = e.status;
152	      }
153	      apply.push(item);
154	    });
155	    return { apply: apply, noop: noop };
156	  }
