  color: var(--ink);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
button { font: inherit; color: inherit; cursor: pointer; background: none; border: none; padding: 0; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }
code { font-family: var(--mono); font-size: 12px; color: #33415c; }
.dim { color: var(--ink-3); }
.small { font-size: 12px; }
.link { color: var(--accent); cursor: pointer; text-decoration: underline; }

/* ---------- 顶栏 ---------- */
.topbar {
  display: flex; align-items: baseline; gap: 12px;
  padding: 8px 14px;
  background: #16283c; color: #fff;
  flex: none;
}
.topbar .brand { font-size: 15px; font-weight: 600; letter-spacing: .5px; }
.topbar .tagline { font-size: 12px; color: #9fb4c9; }
.topbar .spacer { flex: 1; }
.topbar .env { font-size: 11px; color: #9fb4c9; }

/* ---------- 布局 ---------- */
.layout { flex: 1; display: flex; min-height: 0; }
.sidebar {
  width: 262px; flex: none;
  background: var(--panel);
  border-right: 1px solid var(--line);
  display: flex; flex-direction: column; min-height: 0;
}
.side-head {
  padding: 8px 12px 6px;
  font-size: 11px; font-weight: 600; color: var(--ink-3);
  letter-spacing: 1px; text-transform: uppercase;
  border-bottom: 1px solid var(--line);
}
#tree { overflow: auto; padding: 6px 4px 20px; }

.content { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; }

/* ---------- 层级树 ---------- */
.tnode { margin: 1px 0; }
.tkids { margin-left: 16px; border-left: 1px dashed var(--line-strong); padding-left: 4px; }
