}
.trow:hover { background: #eef2f6; }
.trow.scoped { background: var(--accent-soft); }
.trow.scoped .tname { color: var(--accent-ink); font-weight: 600; }
.caret {
  width: 14px; flex: none; text-align: center;
  color: var(--ink-3); font-size: 11px;
  transition: transform .12s;
  cursor: pointer;
}
.caret.open { transform: rotate(90deg); }
.caret.leaf { visibility: hidden; }
.tname { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tcount {
  flex: none; font-size: 11px; color: var(--ink-2);
  background: #eef1f4; border-radius: 8px; padding: 0 6px;
}
.trow.scoped .tcount { background: #d8e6fb; color: var(--ink); }
.tcount b { color: var(--ink); }
.mbar {
  flex: 1 1 24px; max-width: 48px; height: 5px;
  display: flex; border-radius: 3px; overflow: hidden;
  background: #edf0f3;
}
.mbar i { display: block; }

/* ---------- 工具栏 ---------- */
.toolbar {
  flex: none;
  padding: 8px 12px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  display: flex; flex-direction: column; gap: 7px;
}
.toolbar-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
#scope-crumb { font-weight: 600; color: var(--ink); }
#scope-crumb::before { content: "◢"; color: var(--accent); margin-right: 5px; font-size: 11px; }
.search-wrap { flex: 0 1 240px; position: relative; }
.search-wrap input {
  width: 100%; padding: 4px 26px 4px 9px;
  border: 1px solid var(--line-strong); border-radius: var(--radius);
  font: inherit; background: #fbfcfd;
}
.search-wrap input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 2px var(--accent-soft); }
.search-wrap kbd {
  position: absolute; right: 6px; top: 50%; transform: translateY(-50%);
  font: 10px var(--mono); color: var(--ink-3);
  border: 1px solid var(--line); border-radius: 3px; padding: 0 4px; background: #fff;
}
