tr.detail td { background: #fafcfd; padding: 6px 12px 10px 38px; }
.detail-card { display: flex; gap: 22px; flex-wrap: wrap; font-size: 12px; }
.detail-card > div { display: flex; align-items: center; gap: 6px; }
.detail-card b { color: var(--ink-3); font-weight: 500; }
.empty { padding: 42px 0; text-align: center; }
.empty-title { font-size: 14px; color: var(--ink-2); margin-bottom: 4px; }

/* ---------- 操作条 ---------- */
#actionbar {
  flex: none;
  display: flex; align-items: center; gap: 8px;
  padding: 7px 12px;
  background: #1d2f45; color: #e8eef5;
  border-top: 2px solid var(--accent);
}
#actionbar[hidden] { display: none; }
#ab-count b { color: #fff; font-size: 14px; }
.ab-hidden { color: #ffd479; }
#actionbar .spacer { flex: 1; }
#actionbar .btn { background: #2c4260; border-color: #3d5878; color: #dfe9f4; }
#actionbar .btn:hover { border-color: #7ea4d4; color: #fff; }
#actionbar .btn-op-main { background: var(--accent); border-color: var(--accent); color: #fff; }
#actionbar .btn-op-main:hover { background: #3b6fe0; }
#actionbar .btn-danger { background: var(--danger); border-color: var(--danger); }
#actionbar .btn-danger:hover { background: #d43030; }

/* ---------- 状态栏 ---------- */
#statusbar {
  flex: none; position: relative;
  display: flex; align-items: center; gap: 10px;
  padding: 4px 12px;
  background: var(--panel); border-top: 1px solid var(--line);
  font-size: 12px; color: var(--ink-2);
  min-height: 27px;
}
#statusbar .spacer { flex: 1; }
.rc-ok { color: var(--ok); font-weight: 700; }
#ops-panel {
  position: absolute; right: 10px; bottom: 30px;
  width: 380px; max-height: 260px; overflow: auto;
  background: #fff; border: 1px solid var(--line-strong); border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(20, 40, 70, .16);
  padding: 6px 0; z-index: 30;
}
.op-item { padding: 3px 12px; border-bottom: 1px dashed #eef1f4; }
.op-item:last-child { border-bottom: none; }
.op-time { font-family: var(--mono); font-size: 11px; color: var(--ink-3); margin-right: 6px; }
.op-item.undone { opacity: .5; text-decoration: line-through; }
.op-undone { color: var(--warn); font-size: 11px; }

/* ---------- 模态 ---------- */
#modal {
  position: fixed; inset: 0; z-index: 50;
  background: rgba(18, 30, 46, .46);
  display: flex; align-items: center; justify-content: center;
}
#modal[hidden] { display: none; }
.modal-box {
  width: min(760px, 92vw);
  max-height: 84vh;
  display: flex; flex-direction: column;
  background: #fff; border-radius: 10px;
  box-shadow: 0 18px 48px rgba(10, 24, 44, .3);
  overflow: hidden;
}
.modal-head {
  display: flex; align-items: center;
  padding: 10px 16px; border-bottom: 1px solid var(--line);
}
.modal-head h2 { margin: 0; font-size: 14px; }
.modal-head .x { margin-left: auto; color: var(--ink-3); font-size: 16px; padding: 2px 6px; }
.modal-head .x:hover { color: var(--ink); }
.modal-ctrl {
  padding: 10px 16px; border-bottom: 1px solid var(--line);
  display: flex; align-items: center; gap: 10px; background: #f8fafb;
}
.modal-ctrl label { color: var(--ink-2); flex: none; }
.modal-ctrl select, .modal-ctrl input[type=text] {
  font: inherit; padding: 4px 8px;
  border: 1px solid var(--line-strong); border-radius: var(--radius);
  background: #fff; min-width: 240px;
}
.danger-label { display: flex; align-items: center; gap: 6px; color: var(--danger); }
#modal-summary {
  padding: 8px 16px; display: flex; gap: 8px; flex-wrap: wrap;
  border-bottom: 1px solid var(--line);
}
.mchip {
  padding: 2px 10px; border-radius: 10px; font-size: 12px;
  background: #eef2f6; color: var(--ink-2);
}
.mchip b { font-size: 13px; }
.mchip.ok { background: var(--ok-bg); color: var(--ok); }
.mchip.dim2 { background: var(--muted-bg); color: var(--muted); }
#modal-list { flex: 1; overflow: auto; padding: 6px 16px 10px; }
.aff-head {
  position: sticky; top: 0; background: #fff;
  padding: 6px 0 4px; font-size: 11px; font-weight: 600; color: var(--ok);
  letter-spacing: .5px;
}
.aff-head.dim-head { color: var(--ink-3); margin-top: 8px; border-top: 1px dashed var(--line); }
.aff-row {
  display: grid;
  grid-template-columns: 84px minmax(120px, 1.1fr) minmax(120px, 1.3fr) minmax(150px, 1.4fr);
  gap: 10px; align-items: center;
  padding: 3px 0; border-bottom: 1px solid #f2f4f7; font-size: 12px;
}
.aff-row.noop { opacity: .62; }
.aff-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.aff-path { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }
.aff-change .arrow { color: var(--ink-3); margin: 0 3px; }
.modal-error {
  padding: 0 16px; min-height: 20px;
  color: var(--danger); font-size: 12px;
}
.modal-foot {
  display: flex; justify-content: flex-end; gap: 8px;
  padding: 10px 16px; border-top: 1px solid var(--line); background: #f8fafb;
}

/* ---------- 错误横幅 ---------- */
#errbanner {
  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
  z-index: 99; margin-top: 8px;
  background: var(--danger-bg); color: var(--danger);
  border: 1px solid #f3b4b4; border-radius: var(--radius);
  padding: 6px 14px; font-size: 12px;
  box-shadow: 0 6px 18px rgba(120, 20, 20, .18);
}

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: #ccd4dc; border-radius: 5px; border: 2px solid transparent; background-clip: content-box; }
::-webkit-scrollbar-thumb:hover { background: #aeb9c4; background-clip: content-box; }

