1	import { createHash } from "node:crypto";
2	import { mkdir, readFile } from "node:fs/promises";
3	import { join } from "node:path";
4	import type { Page } from "playwright";
5	import { ARTIFACT_CHECK_DEFAULT_SEVERITY } from "prax-validator";
6	import type { MeasurementReceipt } from "prax-validator";
7	
8	export interface CheckContext {
9	  viewport: { width: number; height: number; label?: string | undefined };
10	  screenshotDir: string; // absolute; check writes PNGs here, refs are rebased by the runner
11	}
12	
13	export type CheckOutcome = MeasurementReceipt["checks"][number];
14	
15	interface ElementRecord {
16	  selector: string;
17	  rect: { x: number; y: number; width: number; height: number };
18	  contains: string[];
19	}
20	
21	/**
22	 * layout.responsive_collision (spec §5.3): pairwise intersection of visible
23	 * interactive elements (a, button, input, select, textarea, [role=button],
24	 * [tabindex]) per viewport. Exemptions: ancestor/descendant containment and
25	 * elements declaring an explicit overlay role via [data-overlay]. Reports
26	 * colliding pairs with their rects.
27	 */
28	export async function run(page: Page, ctx: CheckContext): Promise<CheckOutcome> {
29	  const viewportLabel = ctx.viewport.label ?? `${ctx.viewport.width}x${ctx.viewport.height}`;
30	  const elements: ElementRecord[] = await page.evaluate(() => {
31	    const INTERACTIVE = "a,button,input,select,textarea,[role=button],[tabindex]";
32	    const isVisible = (element: Element): boolean => {
33	      const style = window.getComputedStyle(element);
34	      const rect = element.getBoundingClientRect();
35	      return (
36	        style.display !== "none" &&
37	        style.visibility !== "hidden" &&
38	        rect.width > 0 &&
39	        rect.height > 0
40	      );
41	    };
42	    const describe = (element: Element): string => {
43	      const tag = element.tagName.toLowerCase();
44	      if (element.id !== "") return `${tag}#${element.id}`;
45	      const text = (element.textContent ?? "").trim().slice(0, 24);
46	      return text !== "" ? `${tag}[${text}]` : tag;
47	    };
48	    const candidates = Array.from(document.querySelectorAll(INTERACTIVE)).filter(
49	      (element) => !element.hasAttribute("data-overlay") && isVisible(element),
50	    );
51	    return candidates.map((element) => {
52	      const domRect = element.getBoundingClientRect();
53	      return {
54	        selector: describe(element),
55	        rect: { x: domRect.x, y: domRect.y, width: domRect.width, height: domRect.height },
56	        contains: candidates
57	          .filter((other) => other !== element && element.contains(other))
58	          .map((other) => describe(other)),
59	      };
60	    });
61	  });
62	
63	  const pairs: Array<{ a: string; b: string; a_rect: ElementRecord["rect"]; b_rect: ElementRecord["rect"] }> = [];
64	  for (let i = 0; i < elements.length; i += 1) {
65	    for (let j = i + 1; j < elements.length; j += 1) {
66	      const first = elements[i]!;
67	      const second = elements[j]!;
68	      // ancestor/descendant pairs are containment, not collision
69	      if (first.contains.includes(second.selector) || second.contains.includes(first.selector)) continue;
70	      const overlaps =
71	        first.rect.x < second.rect.x + second.rect.width &&
72	        second.rect.x < first.rect.x + first.rect.width &&
73	        first.rect.y < second.rect.y + second.rect.height &&
74	        second.rect.y < first.rect.y + first.rect.height;
75	      if (overlaps) {
76	        pairs.push({ a: first.selector, b: second.selector, a_rect: first.rect, b_rect: second.rect });
77	      }
78	    }
79	  }
80

